# In-memory broadcast job tracker — keys are job UUIDs, values are status dicts
_BROADCAST_JOBS: Dict[str, Dict[str, Any]] = {}
_BROADCAST_JOBS_LOCK = threading.Lock()

def _broadcast_job_path(job_id: str) -> "Path":
    d = Path(DATA_DIR) / "broadcast_jobs"
    d.mkdir(exist_ok=True)
    return d / f"{job_id}.json"

def _broadcast_job_persist(job_id: str, state: Dict[str, Any]) -> None:
    """Write final broadcast job state to disk so it survives restarts."""
    try:
        p = _broadcast_job_path(job_id)
        tmp = p.with_suffix(".tmp")
        tmp.write_text(json.dumps(state), encoding="utf-8")
        tmp.replace(p)
    except Exception:
        pass

def _broadcast_job_load(job_id: str) -> Optional[Dict[str, Any]]:
    """Load a completed broadcast job from disk (fallback when not in memory)."""
    try:
        p = _broadcast_job_path(job_id)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return None

def _broadcast_jobs_evict_old(max_age_hours: int = 4) -> None:
    """Evict completed broadcast jobs to prevent unbounded memory growth."""
    try:
        cutoff = datetime.utcnow() - timedelta(hours=max_age_hours)
        with _BROADCAST_JOBS_LOCK:
            stale = [
                jid for jid, job in _BROADCAST_JOBS.items()
                if job.get("status") in ("done", "error")
                and job.get("started_at")
                and datetime.fromisoformat(str(job["started_at"]).replace("Z", "")) < cutoff
            ]
            for jid in stale:
                _BROADCAST_JOBS.pop(jid, None)
        # Also prune old disk job files
        try:
            d = Path(DATA_DIR) / "broadcast_jobs"
            if d.exists():
                for f in d.glob("*.json"):
                    try:
                        age = datetime.utcnow() - datetime.fromisoformat(
                            json.loads(f.read_text(encoding="utf-8")).get("finished_at", "").replace("Z", "") or "2000-01-01")
                        if age.total_seconds() > max_age_hours * 3600:
                            f.unlink(missing_ok=True)
                    except Exception:
                        pass
        except Exception:
            pass
    except Exception:
        pass


# =========================
# API KEY ENCRYPTION (Fernet / symmetric AES-128-CBC)
# =========================
# Set FIELD_ENCRYPTION_KEY in your environment (Render → Environment).
# Generate one with: python3 -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())"
# If not set, keys are stored as plaintext — a warning is printed at startup.
try:
    from cryptography.fernet import Fernet as _Fernet
    _ENC_KEY_RAW = (os.getenv("FIELD_ENCRYPTION_KEY") or "").strip().encode()
    if _ENC_KEY_RAW:
        _FERNET = _Fernet(_ENC_KEY_RAW)
        print("[STARTUP] FIELD_ENCRYPTION_KEY loaded — API keys will be encrypted at rest.", flush=True)
    else:
        _FERNET = None
        print("[STARTUP] ⚠️  FIELD_ENCRYPTION_KEY not set — API keys stored as plaintext.", flush=True)
except Exception as _enc_err:
    _FERNET = None
    print(f"[STARTUP] ⚠️  Encryption init failed ({_enc_err}) — API keys stored as plaintext.", flush=True)

def _encrypt_field(value: str) -> str:
    """Encrypt a sensitive string. Returns prefixed ciphertext, or plaintext if encryption unavailable."""
    if not value or not _FERNET:
        return value
    try:
        return "enc:" + _FERNET.encrypt(value.encode("utf-8")).decode("utf-8")
    except Exception:
        return value

def _decrypt_field(value: str) -> str:
    """Decrypt a value encrypted by _encrypt_field. Transparently passes through plaintext."""
    if not value:
        return value
    if not value.startswith("enc:"):
        return value   # plaintext (pre-encryption or no key set)
    if not _FERNET:
        return ""      # key missing — return empty rather than expose garbage
    try:
        return _FERNET.decrypt(value[4:].encode("utf-8")).decode("utf-8")
    except Exception:
        return ""


