_PLAN_KEY_ALIASES = {"starter": "solo", "growth": "teams", "pro": "teams"}

def _normalize_plan_key(key: str) -> str:
    """Map legacy plan keys to current ones so existing seat records keep working."""
    k = (key or "solo").strip().lower()
    return _PLAN_KEY_ALIASES.get(k, k) if k not in PLANS else k

# ── Per-plan usage limits ────────────────────────────────────────────────────
MSG_LIMITS   = {"founder": 1000, "solo": 600,  "teams": 2000}
IMAGE_LIMITS = {"founder": 20,   "solo": 15,   "teams": 40}

_MSG_USAGE_LOCK = threading.Lock()

def _msg_usage_path(username: str) -> Path:
    safe = re.sub(r"[^a-zA-Z0-9_-]+", "_", username or "anon")
    return Path(DATA_DIR) / f"msg_usage_{safe}.json"

def _get_msg_usage(username: str) -> Dict[str, Any]:
    """Return {month, count, image_count} for current calendar month. Auto-resets on new month."""
    month = datetime.utcnow().strftime("%Y-%m")
    try:
        path = _msg_usage_path(username)
        if path.exists():
            d = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(d, dict) and d.get("month") == month:
                return {"month": month, "count": int(d.get("count", 0)), "image_count": int(d.get("image_count", 0))}
    except Exception:
        pass
    return {"month": month, "count": 0, "image_count": 0}

def _increment_msg_usage(username: str, *, images: bool = False) -> Dict[str, Any]:
    """Thread-safe increment of message or image counter. Returns updated usage dict."""
    month = datetime.utcnow().strftime("%Y-%m")
    with _MSG_USAGE_LOCK:
        try:
            path = _msg_usage_path(username)
            d = {"month": month, "count": 0, "image_count": 0}
            if path.exists():
                raw = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(raw, dict) and raw.get("month") == month:
                    d = raw
                d["month"] = month
            if images:
                d["image_count"] = int(d.get("image_count", 0)) + 1
            else:
                d["count"] = int(d.get("count", 0)) + 1
            tmp = path.with_suffix(".tmp")
            tmp.write_text(json.dumps(d), encoding="utf-8")
            tmp.replace(path)
            return d
        except Exception:
            return {"month": month, "count": 0, "image_count": 0}

def _user_has_own_key(username: str) -> bool:
    """Return True if the user has saved their own OpenAI or Claude API key (bypasses msg limits)."""
    try:
        u = load_users().get("users", {}).get(username, {})
        s = u.get("settings") or {}
        ok = bool(_decrypt_field((s.get("openai_key") or "").strip()))
        ck = bool(_decrypt_field((s.get("claude_key") or "").strip()))
        return ok or ck
    except Exception:
        return False

def _check_msg_limit(username: str, plan_key: str) -> tuple:
    """Return (allowed, used, limit, image_used, image_limit, has_own_key).
    allowed=True if the user can send another message."""
    if _user_has_own_key(username):
        return (True, 0, 0, 0, 0, True)
    k      = _normalize_plan_key(plan_key)
    limit  = MSG_LIMITS.get(k, 600)
    ilimit = IMAGE_LIMITS.get(k, 20)
    usage  = _get_msg_usage(username)
    used   = usage["count"]
    iused  = usage["image_count"]
    return (used < limit, used, limit, iused, ilimit, False)

def _check_image_limit(username: str, plan_key: str) -> tuple:
    """Return (allowed, used, limit, has_own_key)."""
    if _user_has_own_key(username):
        return (True, 0, 0, True)
    k      = _normalize_plan_key(plan_key)
    ilimit = IMAGE_LIMITS.get(k, 20)
    usage  = _get_msg_usage(username)
    iused  = usage["image_count"]
    return (iused < ilimit, iused, ilimit, False)


def _plan_price_id(plan_key: str) -> str:
    """Return the Stripe price ID for a plan key, falling back to Solo."""
    k = _normalize_plan_key(plan_key)
    p = PLANS.get(k) or PLANS.get("solo") or {}
    return (p.get("price_id") or STRIPE_PRICE_ID_STARTER or STRIPE_PRICE_ID or "").strip()


# ── Founder seat tracking ────────────────────────────────────────────────────
# Module-level lock — shared across ALL calls. A new threading.Lock() inside
# the function would create a different lock per call, providing zero protection.
_FOUNDER_SEATS_LOCK = threading.Lock()

def _load_founder_seats() -> Dict[str, Any]:
    """Return founder seat data: {claimed: int, claimants: [...]}"""
    try:
        if FOUNDER_SEATS_PATH.exists():
            with open(FOUNDER_SEATS_PATH) as f:
                return json.load(f)
    except Exception:
        pass
    return {"claimed": 0, "claimants": []}

def _save_founder_seats(data: Dict[str, Any]) -> None:
    try:
        tmp = Path(str(FOUNDER_SEATS_PATH) + ".tmp")
        tmp.write_text(json.dumps(data), encoding="utf-8")
        tmp.replace(FOUNDER_SEATS_PATH)
    except Exception:
        pass

def _founder_seats_remaining() -> int:
    """How many founder seats are still available."""
    d = _load_founder_seats()
    # FOUNDER_SEATS_SEED = actual signups not captured in the seats file
    FOUNDER_SEATS_SEED = int(os.getenv("FOUNDER_SEATS_SEED", "3"))
    claimed = d.get("claimed", 0) + FOUNDER_SEATS_SEED
    return max(0, FOUNDER_SEATS_MAX - claimed)

def _claim_founder_seat(username: str) -> bool:
    """Atomically claim one founder seat. Returns True if successful."""
    with _FOUNDER_SEATS_LOCK:
        d = _load_founder_seats()
        if d.get("claimed", 0) >= FOUNDER_SEATS_MAX:
            return False
        d["claimed"] = d.get("claimed", 0) + 1
        claimants = d.get("claimants") or []
        if username not in claimants:
            claimants.append(username)
        d["claimants"] = claimants
        _save_founder_seats(d)
        return True

def _founder_weekly_timer() -> Dict[str, Any]:
    """Returns honest seat availability data instead of a fake timer.
    Kept for API compatibility — callers receive remaining + claimed counts."""
    remaining = _founder_seats_remaining()
    claimed   = FOUNDER_SEATS_MAX - remaining
    return {
        "total_seconds": 0,      # deprecated — no longer a timer
        "days":    0,
        "hours":   0,
        "minutes": 0,
        "seconds": 0,
        "seats_remaining": remaining,
        "seats_claimed":   claimed,
        "seats_total":     FOUNDER_SEATS_MAX,
    }


# ── Team Seats System ────────────────────────────────────────────────────────

def _team_seat_limit(plan_key: str) -> int:
    """Return the number of team seats included in a plan (1 = solo/owner only)."""
    k = _normalize_plan_key(plan_key)
    return int((PLANS.get(k) or PLANS.get("solo") or {}).get("team_seats", 1))

def _get_team_owner(username: str) -> Optional[str]:
    """Return the team owner for a user (None if they are the owner)."""
    data = load_users()
    u = (data.get("users") or {}).get(username) or {}
    return u.get("team_owner")

def _get_team_members(owner_username: str) -> List[str]:
    """Return list of team member usernames for an owner."""
    data = load_users()
    u = (data.get("users") or {}).get(owner_username) or {}
    return list(u.get("team_members") or [])

def _get_team_seats_used(owner_username: str) -> int:
    """Seats used = owner (1) + number of active team members."""
    return 1 + len(_get_team_members(owner_username))

def _can_add_team_member(owner_username: str) -> Tuple[bool, str]:
    """Check whether the owner has room for another team member."""
    plan  = _get_user_plan(owner_username)
    limit = _team_seat_limit(plan)
    used  = _get_team_seats_used(owner_username)
    if used >= limit:
        return False, f"Your {(PLANS.get(plan) or {}).get('name','plan')} includes {limit} seat{'s' if limit!=1 else ''}. Upgrade to add more team members."
    return True, ""

def _add_team_member(owner_username: str, member_username: str) -> Tuple[bool, str]:
    """Link a user as a team member of owner. Returns (ok, error_msg)."""
    ok, msg = _can_add_team_member(owner_username)
    if not ok:
        return False, msg
    data  = load_users()
    users = data.get("users") or {}
    owner = users.get(owner_username)
    if not owner:
        return False, "Owner not found."
    member = users.get(member_username)
    if not member:
        return False, "Member not found."
    if member.get("team_owner") and member["team_owner"] != owner_username:
        return False, "User already belongs to another team."
    members = list(owner.get("team_members") or [])
    if member_username not in members:
        members.append(member_username)
    owner["team_members"] = members
    member["team_owner"]  = owner_username
    save_users(data)
    return True, ""

def _remove_team_member(owner_username: str, member_username: str) -> Tuple[bool, str]:
    """Unlink a team member from owner."""
    data  = load_users()
    users = data.get("users") or {}
    owner  = users.get(owner_username)
    member = users.get(member_username)
    if not owner:
        return False, "Owner not found."
    members = list(owner.get("team_members") or [])
    if member_username in members:
        members.remove(member_username)
    owner["team_members"] = members
    if member and member.get("team_owner") == owner_username:
        member["team_owner"] = None
    save_users(data)
    return True, ""


def _get_user_plan(username: str) -> str:
    """Return the plan key ('founder'/'solo'/'teams') for a given username.
    Looks up their seat record. Admins (first user) get 'teams' automatically.
    Falls back to 'solo' if no seat found.
    Result is cached on g per username for the duration of the request.
    """
    # Per-request cache — plan won't change mid-request
    try:
        cache = getattr(g, "_plan_cache", None)
        if cache is None:
            g._plan_cache = {}
            cache = g._plan_cache
        if username in cache:
            return cache[username]
    except RuntimeError:
        cache = None  # no app context (background thread)

    result = "solo"
    try:
        # Admin always gets teams access
        data = load_users()
        users = data.get("users") or {}
        if users:
            first = min(users.values(), key=lambda x: (x.get("created_at") or ""))
            if first.get("username") == username:
                result = "teams"
                if cache is not None:
                    cache[username] = result
                return result
        seats = (_load_seats().get("seats") or {})
        for seat in seats.values():
            if seat.get("claimed_by") == username:
                if seat.get("status") in ("cancelled", "inactive"):
                    result = "solo"  # cancelled users drop back to free tier
                    break
                result = _normalize_plan_key((seat.get("plan") or "solo").strip().lower())
                break
    except Exception:
        pass

    if cache is not None:
        cache[username] = result
    return result

