# _adjust_content_length_for_video removed — modifying global app.config per-request
# is NOT thread-safe and causes a race condition where concurrent requests reset the
# limit to 25 MB mid-upload, killing the connection with a 413 and "Failed to fetch".
# The global ceiling is now 500 MB; individual routes enforce their own size limits.

@app.errorhandler(413)
def _handle_413(e):
    try:
        if (request.path or "").startswith("/api/"):
            return jsonify({"ok": False, "error": "File too large. Maximum upload size is 500 MB."}), 413
    except Exception:
        pass
    raise e

@app.before_request
def _auth_guard() -> Optional[Any]:
    if request.path in ("/login", "/setup", "/reset", "/reset_password", "/register", "/static", "/terms", "/privacy", "/pricing", "/showcase", "/verify", "/verify/resend", "/health", "/ping"):
        return None
    if request.path.startswith("/static/"):
        return None
    if request.path.startswith("/stripe/"):
        return None
    if request.path.startswith("/admin/"):
        # Enforce auth globally for all admin routes — don't rely on per-route checks
        _au = current_user()
        if not _au or not _is_admin_user(_au):
            return redirect(url_for("login"))
        return None

    # allow setup if no users exist
    if request.path.startswith("/setup") and not has_any_user():
        return None

    public_api = {"/api/login", "/api/logout", "/api/reset_request", "/api/reset_password", "/api/me", "/api/csrf_token", "/api/register", "/health", "/ping"}
    if request.path.startswith("/api/") and request.path in public_api:
        return None

    # CSRF check — runs for all authenticated POST/PUT/PATCH/DELETE requests
    if not _csrf_valid():
        if request.path.startswith("/api/"):
            return jsonify({"ok": False, "error": "Invalid or missing CSRF token. Refresh the page and try again."}), 403
        return "Forbidden — invalid CSRF token", 403

    # Clear stale sessions so the login gate shows cleanly instead of half-auth states.
    if session.get("user") and not current_user():
        try:
            session.pop("user", None)
        except Exception:
            pass
        session.modified = True

    if request.path.startswith("/api/") and not current_user():
        resp = jsonify({"ok": False, "error": "Not authenticated"})
        resp.headers["Cache-Control"] = "no-store"
        return resp, 401

    if request.path == "/" and not current_user():
        if not has_any_user():
            return redirect(url_for("setup"))
        return redirect(url_for("login"))

    # attach per-user OpenAI client for this request (best-effort — skip if no key configured)
    u = current_user()
    user_key = ""
    if u:
        user_key = _decrypt_field((((u.get("settings") or {}).get("openai_key")) or "").strip())
    _effective_key = user_key or OPENAI_API_KEY
    if _effective_key:
        try:
            g.openai_client = OpenAI(api_key=_effective_key)
        except Exception:
            g.openai_client = None
    else:
        g.openai_client = None

    return None

def get_openai_client() -> "OpenAI":
    c = getattr(g, "openai_client", None)
    return c or _get_global_openai_client()

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
EMAIL_DRAFT_BLOCK_RE = re.compile(r"```email\s*([\s\S]*?)```", re.IGNORECASE)
EMAIL_HEADER_RE = re.compile(r"^\s*(to|subject|body|email-num|email_num)\s*:\s*(.*)\s*$", re.IGNORECASE)


def now_iso() -> str:
    return datetime.utcnow().isoformat() + "Z"



# Per-path threading locks so concurrent threads don't race on the same file.
_JSON_FILE_LOCKS: Dict[str, threading.Lock] = {}
_JSON_FILE_LOCKS_LOCK = threading.Lock()

def _json_file_lock(path: Path) -> threading.Lock:
    key = str(path.resolve())
    with _JSON_FILE_LOCKS_LOCK:
        if key not in _JSON_FILE_LOCKS:
            _JSON_FILE_LOCKS[key] = threading.Lock()
        return _JSON_FILE_LOCKS[key]

def load_json(path: Path, default: Any) -> Any:
    """Thread-safe JSON read. Holds the per-path lock so reads don't race
    with concurrent atomic writes (tmp → rename)."""
    if not path.exists():
        return default
    lock = _json_file_lock(path)
    with lock:
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return default

def save_json(path: Path, payload: Any) -> None:
    """Thread-safe atomic JSON write.
    Uses a per-path threading.Lock for in-process safety, then writes to a
    .tmp file and renames — so a crash mid-write never corrupts the target.
    """
    lock = _json_file_lock(path)
    with lock:
        try:
            tmp = path.with_suffix(".tmp")
            tmp.write_text(json.dumps(payload, indent=2), encoding="utf-8")
            tmp.replace(path)
        except Exception:
            # Fallback to direct write if rename fails (e.g. cross-device)
            try:
                path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
            except Exception:
                pass



def append_log(name: str, payload: Dict[str, Any]) -> None:
    stamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    safe = re.sub(r"[^a-zA-Z0-9_-]+", "_", name)
    save_json(LOGS_DIR / f"{safe}_{stamp}.json", payload)

# =========================
# STARTUP MIGRATION: Fix saved teammate job titles
# =========================
# load_json / save_json are now defined above — safe to run.
_JOB_TITLE_FIXES = {
    "Willow":   "Language Specialist",
    "Luna":     "Creative Engineer",
    "Sunshine": "Sales Specialist",
}

def _migrate_teammate_job_titles() -> None:
    try:
        if not REGISTRY_PATH.exists():
            return
        raw = REGISTRY_PATH.read_text(encoding="utf-8")
        reg = json.loads(raw)
        installed = reg.get("installed")
        if not isinstance(installed, dict):
            return
        changed = False
        for name, correct_title in _JOB_TITLE_FIXES.items():
            tm = installed.get(name)
            if isinstance(tm, dict) and tm.get("job_title") != correct_title:
                tm["job_title"] = correct_title
                installed[name] = tm
                changed = True
        if changed:
            reg["installed"] = installed
            tmp = REGISTRY_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(reg, indent=2), encoding="utf-8")
            tmp.replace(REGISTRY_PATH)
    except Exception:
        pass

try:
    _migrate_teammate_job_titles()
except Exception:
    pass

# Migrate any custom teammates from global registry into admin's per-user registry
try:
    _migrate_global_registry_once()
except Exception:
    pass

# =========================
# AUTOMATED DATA BACKUPS
# =========================
# Backs up the entire DATA directory to a local /var/backups folder every
# BACKUP_INTERVAL_HOURS hours (default 6). Each backup is a timestamped .tar.gz.
# Keeps the last BACKUP_KEEP copies and deletes older ones automatically.
#
# For off-site backups, set BACKUP_S3_BUCKET + AWS_ACCESS_KEY_ID + AWS_SECRET_ACCESS_KEY
# and each local backup will also be pushed to S3/Backblaze B2.
#
BACKUP_INTERVAL_HOURS = int(os.getenv("BACKUP_INTERVAL_HOURS", "6"))
BACKUP_KEEP           = int(os.getenv("BACKUP_KEEP", "3"))        # 3 × 6h = 18h of local history
BACKUP_S3_BUCKET      = os.getenv("BACKUP_S3_BUCKET", "").strip() # e.g. my-app-backups
# Default to DATA/backups so backups land on the same persistent disk as data.
# Override with BACKUP_DIR=/var/backups/simply_agentic if you have a separate backup volume.
BACKUP_DIR            = Path(os.getenv("BACKUP_DIR", "") or os.path.join(DATA_DIR, "backups"))

def _run_backup() -> None:
    """Create a timestamped .tar.gz of DATA (excluding uploads/backups), prune old copies."""
    import tarfile
    # Dirs that are either too large or self-referential to include in backup
    _BACKUP_EXCLUDE = {"uploads", "backups", "img_jobs"}
    try:
        BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        dest  = BACKUP_DIR / f"data_{stamp}.tar.gz"
        with tarfile.open(dest, "w:gz") as tar:
            for child in DATA.iterdir():
                if child.name in _BACKUP_EXCLUDE:
                    continue
                tar.add(str(child), arcname=f"data/{child.name}")
        print(f"[BACKUP] Created {dest} ({dest.stat().st_size // 1024} KB)", flush=True)

        # Prune oldest backups beyond BACKUP_KEEP
        backups = sorted(BACKUP_DIR.glob("data_*.tar.gz"), key=lambda p: p.name)
        for old in backups[:-BACKUP_KEEP]:
            try:
                old.unlink()
                print(f"[BACKUP] Pruned old backup: {old.name}", flush=True)
            except Exception:
                pass

        # Optional S3/B2 push — requires boto3 and credentials in env
        if BACKUP_S3_BUCKET:
            try:
                import boto3  # type: ignore
                s3 = boto3.client("s3")
                s3_key = f"backups/{dest.name}"
                s3.upload_file(str(dest), BACKUP_S3_BUCKET, s3_key)
                print(f"[BACKUP] Uploaded to s3://{BACKUP_S3_BUCKET}/{s3_key}", flush=True)
            except Exception as e:
                print(f"[BACKUP] S3 upload failed: {e}", flush=True)
    except Exception as e:
        print(f"[BACKUP] Backup failed: {e}", flush=True)

def _backup_loop() -> None:
    """Background thread: run a backup every BACKUP_INTERVAL_HOURS hours."""
    import time
    # Stagger first run by 5 min so it doesn't fire during a cold-start spike
    time.sleep(300)
    while True:
        _run_backup()
        _daemon_heartbeat("backup-loop")
        time.sleep(BACKUP_INTERVAL_HOURS * 3600)

def _start_backup_thread() -> None:
    if BACKUP_INTERVAL_HOURS <= 0:
        print("[BACKUP] Automated backups disabled (BACKUP_INTERVAL_HOURS=0).", flush=True)
        return
    t = threading.Thread(target=_backup_loop, daemon=True, name="backup-loop")
    t.start()
    print(f"[BACKUP] Backup thread started — every {BACKUP_INTERVAL_HOURS}h → {BACKUP_DIR}", flush=True)

try:
    _start_backup_thread()
except Exception as _be:
    print(f"[BACKUP] Could not start backup thread: {_be}", flush=True)

# Prune stale backups immediately on startup so a BACKUP_KEEP change takes effect now
try:
    _startup_backups = sorted(BACKUP_DIR.glob("data_*.tar.gz"), key=lambda p: p.name)
    _pruned = 0
    for _ob in _startup_backups[:-BACKUP_KEEP] if BACKUP_KEEP > 0 else _startup_backups:
        try:
            _ob.unlink()
            _pruned += 1
        except Exception:
            pass
    if _pruned:
        print(f"[BACKUP] Startup pruned {_pruned} old backup(s), keeping {BACKUP_KEEP}.", flush=True)
except Exception:
    pass

try:
    _migrate_json_to_sqlite()
except Exception as _dbe:
    print(f"[DB] SQLite migration error: {_dbe}", flush=True)

try:
    _load_persisted_jobs()
    print("[JOBS] Persisted job state loaded.", flush=True)
except Exception as _je:
    print(f"[JOBS] Could not load persisted jobs: {_je}", flush=True)

# =========================
# DAEMON HEARTBEAT MONITOR
# =========================
_DAEMON_HEARTBEATS: Dict[str, float] = {}  # daemon_name -> last heartbeat monotonic timestamp
_DAEMON_HEARTBEAT_LOCK = threading.Lock()

def _daemon_heartbeat(name: str) -> None:
    """Call from long-running daemon loops to report liveness."""
    import time as _t
    with _DAEMON_HEARTBEAT_LOCK:
        _DAEMON_HEARTBEATS[name] = _t.monotonic()

def _daemon_status() -> Dict[str, Any]:
    """Return liveness status for all tracked daemons."""
    import time as _t
    now = _t.monotonic()
    result = {}
    with _DAEMON_HEARTBEAT_LOCK:
        for name, ts in _DAEMON_HEARTBEATS.items():
            age_s = int(now - ts)
            result[name] = {"last_heartbeat_seconds_ago": age_s, "alive": age_s < 300}
    return result


