def _normalize_lines_to_list(val: Any) -> List[str]:
    if val is None:
        return []
    if isinstance(val, list):
        out = []
        for x in val:
            if x is None:
                continue
            s = str(x).strip()
            if s:
                out.append(s)
        return out
    s = str(val)
    lines = [ln.strip() for ln in s.splitlines()]
    return [ln for ln in lines if ln]


def _sanitize_teammate_update(payload: Dict[str, Any], current: Dict[str, Any]) -> Dict[str, Any]:
    allowed_str_fields = ["job_title", "version", "mission", "thinking_style", "goal", "preferred_model", "tts_voice"]
    allowed_list_fields = ["responsibilities", "will_not_do"]

    updated: Dict[str, Any] = {}

    for k in allowed_str_fields:
        if k in payload:
            v = payload.get(k)
            if v is None:
                continue
            updated[k] = str(v).strip()

    for k in allowed_list_fields:
        if k in payload:
            updated[k] = _normalize_lines_to_list(payload.get(k))

    updated["name"] = current.get("name", "")
    updated["avatar"] = dict(current.get("avatar") or {})
    if "avatar" in payload and isinstance(payload.get("avatar"), dict):
        glyph_raw = (payload["avatar"].get("glyph") or "").strip()
        if glyph_raw:
            clean = _sanitize_svg(glyph_raw)
            if clean:
                updated["avatar"]["glyph"] = clean
        elif payload["avatar"].get("glyph") == "":
            updated["avatar"].pop("glyph", None)

    for k, v in current.items():
        if k not in updated:
            updated[k] = v

    if not isinstance(updated.get("responsibilities"), list):
        updated["responsibilities"] = _normalize_lines_to_list(updated.get("responsibilities"))
    if not isinstance(updated.get("will_not_do"), list):
        updated["will_not_do"] = _normalize_lines_to_list(updated.get("will_not_do"))

    return updated


def _clean_teammate_name(name: str) -> str:
    n = (name or "").strip()
    n = re.sub(r"\s+", " ", n)
    return n


def _avatar_for_installed(defn: Dict[str, Any]) -> Dict[str, Any]:
    """Return the avatar dict, injecting glyph from PREBUILT_LOCKED for built-ins that lack one."""
    av = dict(defn.get("avatar") or {"bg": "#1f2a44", "fg": "#e6edff",
                                      "sigil": (defn.get("name") or "T")[:1].upper()})
    if not av.get("glyph"):
        pb = PREBUILT_LOCKED.get(defn.get("name", ""), {})
        glyph = (pb.get("avatar") or {}).get("glyph", "")
        if glyph:
            av["glyph"] = glyph
    return av


def _sanitize_svg(raw: str) -> str:
    """Strip SVG to only safe elements and attributes. Reject anything suspicious."""
    import re as _re
    m = _re.search(r'<svg[\s\S]*?</svg>', raw, _re.IGNORECASE)
    if not m:
        return ""
    svg = m.group(0)
    svg = _re.sub(r'\son\w+\s*=\s*(?:"[^"]*"|\'[^\']*\')', '', svg, flags=_re.IGNORECASE)
    svg = _re.sub(r'javascript\s*:', '', svg, flags=_re.IGNORECASE)
    SAFE = r'(?:svg|circle|ellipse|line|path|polygon|polyline|rect|g|defs|stop|linearGradient|radialGradient)'
    svg = _re.sub(r'<(?!\/?(?:' + SAFE + r')\b)[^>]+>', '', svg, flags=_re.IGNORECASE)
    return svg.strip()


def _make_avatar_for(name: str) -> Dict[str, str]:
    palette = [
        ("#1e3a8a", "#e6edff"),
        ("#4c1d95", "#e6edff"),
        ("#0f766e", "#e6edff"),
        ("#7c2d12", "#e6edff"),
        ("#374151", "#e6edff"),
        ("#9a3412", "#e6edff"),
        ("#111827", "#e6edff"),
        ("#155e75", "#e6edff"),
        ("#3f6212", "#e6edff"),
        ("#7f1d1d", "#e6edff"),
    ]
    idx = abs(hash(name)) % len(palette)
    bg, fg = palette[idx]
    sigil = (name[:1] or "T").upper()
    return {"bg": bg, "fg": fg, "sigil": sigil}


def create_teammate(payload: Dict[str, Any], username: str = "") -> Dict[str, Any]:
    name = _clean_teammate_name(payload.get("name", ""))
    if not name:
        raise ValueError("Missing teammate name")

    if len(name) > 32:
        raise ValueError("Teammate name must be 32 characters or less")

    uname = username or _get_session_username()
    reg = load_registry(uname)
    installed = reg.get("installed") or {}

    if name in installed:
        raise ValueError("Teammate name already exists")

    job_title = str(payload.get("job_title", "")).strip()
    version = str(payload.get("version", "v1.0")).strip() or "v1.0"
    mission = str(payload.get("mission", "")).strip()
    thinking_style = str(payload.get("thinking_style", "")).strip()
    goal = str(payload.get("goal", "")).strip()
    responsibilities = _normalize_lines_to_list(payload.get("responsibilities"))
    will_not_do = _normalize_lines_to_list(payload.get("will_not_do"))

    t = {
        "name": name,
        "job_title": job_title,
        "version": version,
        "mission": mission,
        "responsibilities": responsibilities,
        "thinking_style": thinking_style,
        "will_not_do": will_not_do,
        "goal": goal,
        "avatar": _make_avatar_for(name),
        "custom": True,
        "created_by": uname,
        "preferred_model": str(payload.get("preferred_model", "")).strip(),
        "tts_voice": str(payload.get("tts_voice", "alloy")).strip() or "alloy",
    }

    installed[name] = t
    reg["installed"] = installed

    order = reg.get("installed_order") or []
    order.append(name)
    reg["installed_order"] = order

    active = reg.get("active_order") or []
    active.append(name)
    reg["active_order"] = active

    save_registry(reg, uname)
    return t


def set_active_order(active_order: List[str], username: str = "") -> List[str]:
    uname = username or _get_session_username()
    reg = load_registry(uname)
    installed = reg.get("installed") or {}
    installed_order = reg.get("installed_order") or []

    seen = set()
    cleaned: List[str] = []
    for n in active_order or []:
        if not isinstance(n, str):
            continue
        n2 = n.strip()
        if not n2:
            continue
        if n2 not in installed:
            continue
        if n2 in seen:
            continue
        seen.add(n2)
        cleaned.append(n2)

    final = [n for n in installed_order if n in cleaned]

    reg["active_order"] = final
    save_registry(reg, uname)
    return final


