@app.get("/api/admin/seats")
def api_admin_seats_get():
    u = current_user()
    if not u or not _is_admin_user(u):
        return jsonify({"ok": False, "error": "Admin only"}), 403
    data = _load_seats()
    seats = data.get("seats") or {}
    seat_list = sorted(seats.items(), key=lambda x: x[1].get("seat_num", 999))
    return jsonify({"ok": True, "seats": [{"code": k, **v} for k, v in seat_list]})

@app.post("/api/admin/seats/generate")
def api_admin_seats_generate():
    """Generate N new seat codes."""
    u = current_user()
    if not u or not _is_admin_user(u):
        return jsonify({"ok": False, "error": "Admin only"}), 403
    payload = request.get_json(silent=True) or {}
    count        = max(1, min(int(payload.get("count", 1)), 50))
    holder_name  = (payload.get("holder_name")  or "").strip()[:120]
    holder_email = (payload.get("holder_email") or "").strip()[:200]
    plan_key     = _normalize_plan_key((payload.get("plan") or "solo").strip().lower())
    if plan_key not in PLANS:
        plan_key = "solo"
    plan_info    = PLANS.get(plan_key) or PLANS["solo"]
    plan_name    = plan_info.get("name", "Solo Operator")
    data = _load_seats()
    seats = data.get("seats") or {}
    existing_nums = [v.get("seat_num", 0) for v in seats.values()]
    next_num = max(existing_nums, default=0) + 1
    new_codes = []
    for i in range(count):
        code = f"SA-{secrets.token_urlsafe(8).upper()[:8]}"
        while code in seats:
            code = f"SA-{secrets.token_urlsafe(8).upper()[:8]}"
        seats[code] = {
            "seat_num":    next_num + i,
            "label":       holder_name if (count == 1 and holder_name) else f"Seat #{next_num + i}",
            "status":      "active",
            "claimed_by":  None,
            "created_at":  now_iso(),
            "claimed_at":  None,
            "notes":       payload.get("notes", ""),
            "holder_name":  holder_name,
            "holder_email": holder_email,
            "source":       "manual",
            "plan":         plan_key,
            "plan_name":    plan_name,
        }
        new_codes.append(code)
    data["seats"] = seats
    _save_seats(data)
    return jsonify({"ok": True, "generated": new_codes})

@app.post("/api/admin/seats/<code>/update")
def api_admin_seat_update(code: str):
    """Update a seat's label, status, notes, holder_name, or holder_email."""
    u = current_user()
    if not u or not _is_admin_user(u):
        return jsonify({"ok": False, "error": "Admin only"}), 403
    data = _load_seats()
    seats = data.get("seats") or {}
    if code not in seats:
        return jsonify({"ok": False, "error": "Seat not found"}), 404
    payload = request.get_json(silent=True) or {}
    if "label" in payload:
        seats[code]["label"] = (payload["label"] or "").strip()[:80]
    if "status" in payload and payload["status"] in ("active", "inactive"):
        seats[code]["status"] = payload["status"]
    if "notes" in payload:
        seats[code]["notes"] = (payload["notes"] or "").strip()[:300]
    if "holder_name" in payload:
        seats[code]["holder_name"] = (payload["holder_name"] or "").strip()[:120]
    if "holder_email" in payload:
        seats[code]["holder_email"] = (payload["holder_email"] or "").strip()[:200]
    if "plan" in payload:
        plan_key = _normalize_plan_key((payload["plan"] or "solo").strip().lower())
        if plan_key not in PLANS:
            plan_key = "solo"
        seats[code]["plan"]      = plan_key
        seats[code]["plan_name"] = (PLANS.get(plan_key) or PLANS["solo"]).get("name", "Solo Operator")
    data["seats"] = seats
    _save_seats(data)
    return jsonify({"ok": True, "seat": {"code": code, **seats[code]}})

