@app.get("/api/user/settings")
def api_get_user_settings():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    settings = (u.get("settings") or {})
    smtp = (settings.get("smtp") or {})

    key = _decrypt_field((settings.get("openai_key") or "").strip())
    key_hint = ("••••" + key[-4:]) if len(key) >= 4 else ("••••" if key else "")

    claude_key = _decrypt_field((settings.get("claude_key") or "").strip())
    claude_hint = ("••••" + claude_key[-4:]) if len(claude_key) >= 4 else ("••••" if claude_key else "")

    safe_smtp = {
        "host": smtp.get("host", ""),
        "port": smtp.get("port", 587),
        "user": smtp.get("user", ""),
        "from_name": smtp.get("from_name", "")
    }
    return jsonify({
        "ok": True,
        "settings": {
            "has_openai_key":       bool(key),
            "openai_key_hint":      key_hint,
            "has_claude_key":       bool(claude_key),
            "claude_key_hint":      claude_hint,
            "global_default_model": (settings.get("global_default_model") or "").strip(),
            "smart_routing": bool(settings.get("smart_routing")),
            "gmail_oauth_connected": bool((settings.get("gmail_oauth") or {}).get("refresh_token") or (settings.get("gmail_oauth") or {}).get("access_token")),
            "smtp": safe_smtp,
            "tooltip_level": (settings.get("tooltip_level") or "medium"),  # off | low | medium | high
            "theme": (settings.get("theme") or {})  # ui customisation prefs
        }
    })



@app.post("/api/user/change_password")
def api_change_password():
    """In-app password change — requires current password for verification."""
    rl = _check_rate_limit("change_password", 5)  # 5 attempts/min — brute-force protection
    if rl: return rl
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    p = request.get_json(force=True, silent=True) or {}
    current_pw = (p.get("current_password") or "").strip()
    new_pw     = (p.get("new_password")     or "").strip()
    confirm_pw = (p.get("confirm_password") or "").strip()
    if not current_pw or not new_pw:
        return jsonify({"ok": False, "error": "Current and new password are required."}), 400
    if new_pw != confirm_pw:
        return jsonify({"ok": False, "error": "New passwords do not match."}), 400
    ok, msg = _validate_password_strength(new_pw)
    if not ok:
        return jsonify({"ok": False, "error": msg}), 400
    data = load_users()
    user_rec = (data.get("users") or {}).get(uname)
    if not user_rec:
        return jsonify({"ok": False, "error": "User not found."}), 404
    if not check_password_hash(user_rec.get("password_hash", ""), current_pw):
        return jsonify({"ok": False, "error": "Current password is incorrect."}), 403
    user_rec["password_hash"] = generate_password_hash(new_pw)
    user_rec["updated_at"] = now_iso()
    data["users"][uname] = user_rec
    save_users(data)
    _audit_log("password_changed", {}, username=uname)
    # Invalidate the current session so all other devices are logged out
    session.clear()
    return jsonify({"ok": True, "message": "Password updated successfully. Please log in again."})


@app.post("/api/smtp/test")
def api_smtp_test():
    """Test SMTP credentials without sending a real email."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    p = request.get_json(silent=True) or {}
    host = (p.get("host") or SMTP_HOST or "").strip()
    port = int(p.get("port") or SMTP_PORT or 587)
    user = (p.get("user") or SMTP_USER or "").strip()
    pw   = (p.get("password") or SMTP_PASS or "").strip()
    if not host or not user:
        return jsonify({"ok": False, "error": "Host and username are required"}), 400
    try:
        with smtplib.SMTP(host, port, timeout=10) as srv:
            srv.ehlo()
            srv.starttls()
            srv.ehlo()
            if pw: srv.login(user, pw)
        return jsonify({"ok": True, "message": "SMTP connection successful!"})
    except smtplib.SMTPAuthenticationError:
        return jsonify({"ok": False, "error": "Authentication failed — check username and password."})
    except smtplib.SMTPConnectError as e:
        return jsonify({"ok": False, "error": f"Could not connect to {host}:{port} — {str(e)[:100]}"})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:200]})

@app.post("/api/user/settings")
def api_set_user_settings():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    data = request.get_json(force=True) or {}
    openai_key = (data.get("openai_key") or "").strip()
    claude_key = (data.get("claude_key") or "").strip()
    global_default_model = (data.get("global_default_model") or "").strip()

    # onboarding_openai_key: mark OpenAI key step when a non-empty key is being saved
    # NOTE: this must run AFTER parsing the request body so we check the NEW key, not the old one
    try:
        uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
        if openai_key:
            _mark_onboarding_step(uname, "preferred_ai", True)
    except Exception:
        pass

    smtp_in = data.get("smtp") or {}
    if not isinstance(smtp_in, dict):
        smtp_in = {}

    smtp_host = (smtp_in.get("host") or "").strip()
    smtp_port = int(smtp_in.get("port") or 587)
    smtp_user = (smtp_in.get("user") or "").strip()
    smtp_pass = (smtp_in.get("pass") or "").strip()
    smtp_from_name = (smtp_in.get("from_name") or "").strip()

    users = load_users()
    uname = u.get("username")
    rec = (users.get("users") or {}).get(uname) or u

    rec.setdefault("settings", {})
    # Only overwrite the stored key when a new non-empty value is submitted.
    # The settings modal intentionally leaves the field blank (shows a hint),
    # so a blank submission must never clear a working saved key.
    if openai_key and len(openai_key) >= 20:
        rec["settings"]["openai_key"] = _encrypt_field(openai_key)
    if claude_key and len(claude_key) >= 20:
        rec["settings"]["claude_key"] = _encrypt_field(claude_key)
    if global_default_model:
        rec["settings"]["global_default_model"] = global_default_model
    if "smart_routing" in (data or {}):
        rec["settings"]["smart_routing"] = bool(data.get("smart_routing"))

    # Tooltip level — always save when present (including "off")
    tooltip_level = (data.get("tooltip_level") or "").strip().lower()
    if tooltip_level in ("off", "low", "medium", "high"):
        rec["settings"]["tooltip_level"] = tooltip_level

    # UI theme / customisation — full replace so reset (empty dict) clears correctly
    theme_in = data.get("theme")
    if isinstance(theme_in, dict):
        allowed_theme_keys = {
            "table_color", "table_glow_opacity",
            "task_glow_color", "event_color",
            "seat_glow_color", "nav_style",
            "font_family", "font_size",
            "arena_bg_color", "accent_color",
            "bg_color", "bg_brightness",
            "cal_glow_color", "cal_glow_opacity",
        }
        rec["settings"]["theme"] = {
            k: v.strip()
            for k, v in theme_in.items()
            if k in allowed_theme_keys and isinstance(v, str) and len(v) <= 80
        }

    rec["settings"].setdefault("smtp", {})
    if smtp_host != "":
        rec["settings"]["smtp"]["host"] = smtp_host
    rec["settings"]["smtp"]["port"] = smtp_port
    if smtp_user != "":
        rec["settings"]["smtp"]["user"] = smtp_user
    if smtp_pass != "":
        rec["settings"]["smtp"]["pass"] = smtp_pass
    if smtp_from_name != "":
        rec["settings"]["smtp"]["from_name"] = smtp_from_name

    rec["updated_at"] = now_iso()
    users["users"][uname] = rec
    save_users(users)

    append_log("user_settings_updated", {"user": uname, "updated_at": now_iso(), "fields": list(data.keys())})
    changed_fields = [k for k in ("openai_key", "claude_key", "global_default_model", "tooltip_level", "smtp") if k in data]
    if changed_fields:
        _audit_log("settings_updated", {"changed_fields": changed_fields}, username=uname)
    return jsonify({"ok": True})


