# Allowlisted upload extensions — executables, scripts & server files are blocked
UPLOAD_ALLOWED_EXTENSIONS = {
    # Images
    ".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".ico", ".bmp", ".tiff",
    # Documents
    ".pdf", ".txt", ".md", ".csv", ".json", ".xml", ".rtf",
    # Office
    ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".odt", ".ods", ".odp",
    # Audio/Video (for future use)
    ".mp3", ".mp4", ".wav", ".ogg", ".m4a", ".mov", ".webm",
    # Archives
    ".zip", ".tar", ".gz",
}

def _upload_extension_allowed(filename: str) -> bool:
    ext = Path(filename).suffix.lower()
    return ext in UPLOAD_ALLOWED_EXTENSIONS


@app.post("/api/upload")
def api_upload():
    _rl = _check_rate_limit("upload", RATE_LIMIT_UPLOAD)
    if _rl: return _rl
    if "file" not in request.files:
        return jsonify({"ok": False, "error": "Missing file field"}), 400

    f = request.files["file"]
    if not f or not f.filename:
        return jsonify({"ok": False, "error": "Empty upload"}), 400

    filename = secure_filename(f.filename)
    if not filename:
        return jsonify({"ok": False, "error": "Invalid filename"}), 400

    if not _upload_extension_allowed(filename):
        return jsonify({"ok": False, "error": f"File type not allowed. Allowed types: images, PDFs, documents, CSV, JSON, ZIP."}), 400

    if request.content_length and request.content_length > MAX_UPLOAD_BYTES:
        return jsonify({"ok": False, "error": f"File too large. Maximum {MAX_UPLOAD_MB} MB allowed."}), 413

    file_id = uuid.uuid4().hex
    subdir = datetime.utcnow().strftime("%Y%m%d")
    (UPLOADS_DIR / subdir).mkdir(parents=True, exist_ok=True)

    out_path = UPLOADS_DIR / subdir / f"{file_id}_{filename}"
    try:
        f.save(out_path)
    except OSError as _fs_err:
        return jsonify({"ok": False, "error": f"Upload failed — storage error. Please try again. ({str(_fs_err)[:80]})"}), 500

    size_bytes = out_path.stat().st_size if out_path.exists() else 0
    if size_bytes > MAX_UPLOAD_BYTES:
        try:
            out_path.unlink()
        except Exception:
            pass
        return jsonify({"ok": False, "error": f"File too large. Maximum {MAX_UPLOAD_MB} MB allowed."}), 413
    mimetype = (f.mimetype or "").strip()

    # Require authenticated owner — fail explicitly rather than creating an orphaned file
    _u = current_user()
    if not _u:
        try: out_path.unlink()
        except Exception: pass
        return jsonify({"ok": False, "error": "Session expired — please refresh and try again."}), 401
    owner = (_u.get("username") if isinstance(_u, dict) else None) or ""
    try:
        if owner:
            _award_points(owner, "Uploaded a file", 20)
    except Exception:
        pass
    rec = {
        "id": file_id,
        "filename": filename,
        "relpath": str(Path(subdir) / f"{file_id}_{filename}"),
        "mimetype": mimetype,
        "size_bytes": size_bytes,
        "uploaded_at": now_iso(),
        "owner": owner,
    }
    add_upload_record(file_id, rec)

    append_log("upload", rec)
    return jsonify({"ok": True, "file": rec})

@app.get("/api/images")
def api_images_list():
    """List stored images (includes AI-generated images and uploaded images)."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    only_ai = (request.args.get("only_ai") or "").strip().lower() in ("1","true","yes","y","on")

    idx = load_upload_index()
    files = list((idx.get("files") or {}).values())

    def _is_image(rec: Dict[str, Any]) -> bool:
        mt = (rec.get("mimetype") or "").lower()
        fn = (rec.get("filename") or "").lower()
        if mt.startswith("image/"):
            return True
        if fn.endswith((".png",".jpg",".jpeg",".webp",".gif",".svg")):
            return True
        return False

    out = []
    for rec in files:
        if not isinstance(rec, dict):
            continue
        if not _is_image(rec):
            continue
        if only_ai and (rec.get("kind") != "ai_image"):
            continue
        # If record has owner, enforce per-user privacy; otherwise show.
        owner = (rec.get("owner") or "").strip()
        if owner and owner != uname:
            continue
        r = dict(rec)
        r["url"] = f"/uploads/{r.get('relpath','')}"
        out.append(r)

    # newest first
    out.sort(key=lambda r: (r.get("uploaded_at") or ""), reverse=True)
    return jsonify({"ok": True, "images": out})


