def _make_token() -> str:
    return secrets.token_urlsafe(18)

def _hash_token(token: str) -> str:
    if not token:
        return ""
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


@app.get("/pricing")
def pricing_page():
    stripe_on      = _stripe_ready()
