@app.get("/verify-2fa")
def verify_2fa():
    if not _get_2fa_pending_user():
        return redirect(url_for("login"))
    return _2FA_HTML.format(app_title=APP_TITLE, error="")

@app.post("/verify-2fa")
def verify_2fa_post():
    pending = _get_2fa_pending_user()
    if not pending:
        return redirect(url_for("login"))
    # Rate-limit 2FA attempts using the same lockout system as login
    _2fa_key = f"2fa:{pending.lower().strip()}"
    _allowed, _lock_msg = _check_login_allowed(_2fa_key)
    if not _allowed:
        return _2FA_HTML.format(app_title=APP_TITLE, error=f"<div class='err'>{_lock_msg}</div>")
    code = (request.form.get("code") or "").strip()
    data = load_users()
    u = (data.get("users") or {}).get(pending)
    raw_secret = _decrypt_field((u.get("totp") or {}).get("secret", ""))
    if not u or not _totp_verify(raw_secret, code):
        _record_login_failure(_2fa_key)
        return _2FA_HTML.format(app_title=APP_TITLE, error="<div class='err'>Invalid code. Please try again.</div>")
    _clear_login_failures(_2fa_key)
    # 2FA passed — complete login
    remember = session.pop("_2fa_remember", False)
    next_url = session.pop("_2fa_next", "")
    session.pop("_2fa_pending_user", None)
    session.clear()  # Prevent session fixation — regenerate session on 2FA verify
    session["user"] = pending
    session.permanent = bool(remember)
    if remember:
        pass  # session lifetime already set at startup in app.config
    if next_url and next_url.startswith("/") and not next_url.startswith("//"):
        return redirect(next_url)
    return redirect(url_for("index"))

@app.get("/api/user/2fa/status")
def api_2fa_status():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    return jsonify({"ok": True, "enabled": _user_has_2fa(u)})

@app.post("/api/user/2fa/setup")
def api_2fa_setup():
    """Generate a new TOTP secret. Returns secret + otpauth URI. Not yet enabled until /confirm."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    secret = _totp_generate_secret()
    uri = _totp_uri(secret, uname)
    # Store provisionally — not enabled yet
    session["_2fa_setup_secret"] = secret
    return jsonify({"ok": True, "secret": secret, "uri": uri})

@app.post("/api/user/2fa/confirm")
def api_2fa_confirm():
    """Verify user scanned QR correctly, then enable 2FA."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    code = (request.get_json(silent=True) or {}).get("code", "").strip()
    secret = session.get("_2fa_setup_secret", "")
    if not secret:
        return jsonify({"ok": False, "error": "No setup in progress. Call /api/user/2fa/setup first."}), 400
    if not _totp_verify(secret, code):
        return jsonify({"ok": False, "error": "Invalid code — please try again."}), 400
    data = load_users()
    users = data.get("users") or {}
    if uname not in users:
        return jsonify({"ok": False, "error": "User not found"}), 404
    users[uname]["totp"] = {"enabled": True, "secret": _encrypt_field(secret), "enabled_at": now_iso()}
    users[uname]["updated_at"] = now_iso()
    data["users"] = users
    save_users(data)
    session.pop("_2fa_setup_secret", None)
    return jsonify({"ok": True, "message": "Two-factor authentication enabled."})

@app.post("/api/user/2fa/disable")
def api_2fa_disable():
    """Disable 2FA (requires current password confirmation)."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    body = request.get_json(silent=True) or {}
    pw = (body.get("password") or "").strip()
    if not pw or not check_password_hash(u.get("password_hash", ""), pw):
        return jsonify({"ok": False, "error": "Incorrect password"}), 403
    data = load_users()
    users = data.get("users") or {}
    if uname in users:
        users[uname]["totp"] = {"enabled": False, "secret": "", "disabled_at": now_iso()}
        users[uname]["updated_at"] = now_iso()
        data["users"] = users
        save_users(data)
    return jsonify({"ok": True, "message": "Two-factor authentication disabled."})


# ===== NEW: Account registration (additive) =====
def _signup_enabled() -> bool:
    # Explicit env override always wins
    v = (os.getenv("ALLOW_SIGNUP") or "").strip().lower()
    if v in ("1","true","yes","y","on"):
        return True
    if v in ("0","false","no","n","off"):
        return False
    # First-run: no users yet → allow setup
    if not has_any_user():
        return True
    # Stripe is configured → signup is always open because payment IS the gate.
    # The access code (seat code) is what controls who actually gets in.
    if _stripe_ready():
        return True
    # No Stripe, users already exist, no explicit flag → closed by default
    return False

def _require_invite_code() -> bool:
    v = (os.getenv("REQUIRE_INVITE_CODE") or "").strip().lower()
    return v in ("1","true","yes","y","on")

def _invite_code_value() -> str:
    return (os.getenv("INVITE_CODE") or "").strip()

@app.get("/register")
def register_get():
    _ref = (request.args.get("ref") or "").strip()
    if _ref: session["_ref_code"] = _ref
    allow = _signup_enabled()
    if not allow:
        return redirect(url_for("login"))

    stripe_code  = None
    stripe_email = None
    stripe_err   = None
    stripe_session = (request.args.get("stripe_session") or "").strip()
    selected_plan  = _normalize_plan_key((request.args.get("plan") or "solo").strip().lower())
    if selected_plan not in PLANS:
        selected_plan = "solo"

    if stripe_session:
        code, email = _stripe_session_code(stripe_session)
        if code:
            stripe_code  = code
            stripe_email = email
        else:
            stripe_err = "We couldn't verify your payment. Please contact support or try again."

    resp = make_response(render_template_string(
        REGISTER_HTML,
        app_title=APP_TITLE,
        error=stripe_err,
        ok=("Payment verified! Your access code has been pre-filled below." if stripe_code else None),
        require_code=has_any_user(),
        stripe_code=stripe_code,
        stripe_email=stripe_email,
        stripe_enabled=_stripe_ready(),
        selected_plan=selected_plan,
        plan_name=(PLANS.get(selected_plan) or {}).get("name", ""),
    ))
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp

@app.post("/register")
def register_post():
    if not _signup_enabled():
        return render_template_string(LOGIN_HTML, app_title=APP_TITLE, error="Account creation is disabled.", allow_setup=(not has_any_user()), allow_signup=False)
    # Rate limit registration attempts by IP — prevents spam account creation
    _ip_reg = _get_client_ip() or "unknown"
    _reg_ok, _reg_msg = _rate_limit_check(f"register:{_ip_reg}", 10)
    if not _reg_ok:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE,
            error="Too many registration attempts. Please wait before trying again.",
            ok=None, require_code=True, stripe_code=None, stripe_email=None,
            stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    username = _clean_username(request.form.get("username",""))
    email = (request.form.get("email","") or "").strip()
    pw = (request.form.get("password","") or "").strip()
    pw2 = (request.form.get("password2","") or "").strip()

    if not username or len(username) < 3:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="Username must be at least 3 characters.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    if len(username) > 40:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="Username must be 40 characters or fewer.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    if email and not EMAIL_RE.match(email):
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="Please enter a valid email address.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    _pw_ok, _pw_err = _validate_password_strength(pw)
    if not _pw_ok:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error=_pw_err, ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    if pw != pw2:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="Passwords do not match.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")
    if not request.form.get("tos_accepted"):
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="You must accept the Terms of Service to create an account.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")

    # First user = admin, no code needed. All others need a valid seat code.
    is_first_user = not has_any_user()
    seat_code = ""
    if not is_first_user:
        seat_code = (request.form.get("invite_code") or "").strip().upper()
        ok, err = _is_valid_seat_code(seat_code)
        if not ok:
            return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error=err, ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")

    data = load_users()
    users = data.get("users") or {}
    if username in users:
        return render_template_string(REGISTER_HTML, app_title=APP_TITLE, error="That username is already taken.", ok=None, require_code=True, stripe_code=None, stripe_email=None, stripe_enabled=_stripe_ready(), selected_plan="solo", plan_name="")

    # ── Email verification ────────────────────────────────────────────────────
    # Skip for: first user (admin, no SMTP yet), or when SMTP is not configured,
    # or when no email address was given.
    smtp_configured = bool(SMTP_USER and SMTP_PASS and SMTP_HOST)
    needs_verification = (not is_first_user) and smtp_configured and bool(email)

    if needs_verification:
        code = str(secrets.randbelow(900000) + 100000)  # 6-digit code
        token = secrets.token_urlsafe(32)
        pending = _load_pending_verifications()
        # Prune old tokens for the same username/email before adding new one
        pending = {t: r for t, r in pending.items()
                   if r.get("username") != username and r.get("email") != email}
        pending[token] = {
            "username":     username,
            "pw_hash":      generate_password_hash(pw),
            "email":        email,
            "seat_code":    seat_code,
            "is_first_user": is_first_user,
            "code":         code,
            "created_at":   now_iso(),
        }
        _save_pending_verifications(pending)
        # Send the code
        try:
            send_email_smtp(
                to_addr=email,
                subject=f"Your {APP_TITLE} verification code",
                body=(
                    f"Hi {username},\n\n"
                    f"Your verification code is: {code}\n\n"
                    f"Enter this code on the verification page to activate your account.\n"
                    f"This code expires in 30 minutes.\n\n"
                    f"If you didn't create this account, you can safely ignore this email.\n\n"
                    f"— {SMTP_FROM_NAME or APP_TITLE}"
                ),
                from_name=SMTP_FROM_NAME or APP_TITLE,
                from_addr=SMTP_USER,
            )
        except Exception as e:
            print(f"[VERIFY] Failed to send verification email to {email}: {e}", flush=True)
            # Don't block registration if email fails — fall through to direct creation
            needs_verification = False

    if needs_verification:
        session["_pending_verify_token"] = token
        session.modified = True
        return redirect(url_for("verify_email_page"))

    # ── Direct registration (first user, no SMTP, or no email) ───────────────
    users[username] = _new_user(username, pw, email=email, is_admin=is_first_user)
    users[username]["email_verified"] = True
    data["users"] = users
    save_users(data)

    if not is_first_user and seat_code:
        try:
            _claim_seat_code(seat_code, username)
        except Exception:
            pass

    session["user"] = username
    session.permanent = True
    _audit_log("register", {"email": email, "is_admin": is_first_user, "direct": True}, username=username)
    # Referral credit
    _ref = (session.pop("_ref_code", None) or "").strip()
    if _ref:
        _referrer = _find_referrer_by_code(_ref)
        if _referrer and _referrer != username:
            _record_referral(_referrer, email or username)
            _award_points(username, "Joined via referral", 50)

    # Welcome email — fire-and-forget, never blocks the redirect
    if email and not is_first_user:
        _base = (PUBLIC_BASE_URL or "").rstrip("/") or "https://simplyagentic.ai"
        threading.Thread(target=_send_platform_email, args=(
            email,
            f"Welcome to Simply Agentic AI — you're in 🎉",
            f"""Hi {username},

Welcome to Simply Agentic AI — your AI-powered business command center.

Here's how to get started in the next 5 minutes:

1. Open the Command Center and click any teammate seat to start a conversation.
2. Press keys 1–7 on your keyboard to switch between teammates instantly.
3. Type ? at any time to see all keyboard shortcuts.
4. Head to Settings to connect your OpenAI key for the best results.

Your team is ready. Press 1 and say hello to Sunshine.

If you ever need help, just reply to this email.

— The Simply Agentic AI Team
{_base}
""",
        ), daemon=True).start()

    # Admin signup alert — notify the platform owner whenever a new user joins
    _admin_notify_email = SMTP_USER
    if _admin_notify_email and not is_first_user:
        _signup_time = datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        _base2 = (PUBLIC_BASE_URL or "").rstrip("/")
        threading.Thread(target=_send_platform_email, args=(
            _admin_notify_email,
            f"[{APP_TITLE}] New signup: {username}",
            f"""New user just joined your platform!

Username : {username}
Email    : {email or "(not provided)"}
Time     : {_signup_time}
Invite   : {seat_code or "(open signup)"}

View your admin panel: {_base2}/admin

— {APP_TITLE} Notifications
""",
        ), daemon=True).start()

    return redirect(url_for("index"))
_PENDING_VERIFICATIONS_PATH = DATA / "pending_verifications.json"

def _load_pending_verifications() -> Dict[str, Any]:
    return load_json(_PENDING_VERIFICATIONS_PATH, {})

def _save_pending_verifications(data: Dict[str, Any]) -> None:
    # Prune any entries older than 60 minutes
    cutoff = (datetime.utcnow() - timedelta(minutes=60)).isoformat() + "Z"
    data = {t: r for t, r in data.items() if (r.get("created_at") or "") >= cutoff}
    save_json(_PENDING_VERIFICATIONS_PATH, data)

