@app.post("/verify")
def verify_email_post():
    token = session.get("_pending_verify_token", "")
    if not token:
        return redirect(url_for("register_get"))
    # Rate limit: max 10 attempts per token to prevent brute-force of 6-digit codes
    _vrl = _check_rate_limit(f"verify:{token[:16]}", 10)
    if _vrl: return _vrl
    pending = _load_pending_verifications()
    rec = pending.get(token)
    if not rec:
        return render_template_string(_VERIFY_HTML, app_title=APP_TITLE,
            email="", error="Verification session expired. Please register again.")

    submitted = (request.form.get("code") or "").strip().replace(" ", "")
    if not hmac.compare_digest(submitted, str(rec.get("code", ""))):
        return render_template_string(_VERIFY_HTML, app_title=APP_TITLE,
            email=rec.get("email",""), error="Incorrect code. Please try again.")

    # Code matches — create the user
    username    = rec["username"]
    email       = rec.get("email", "")
    is_first    = rec.get("is_first_user", False)
    seat_code   = rec.get("seat_code", "")

    data = load_users()
    users = data.get("users") or {}
    if username not in users:
        u_rec = _new_user(username, "placeholder", email=email, is_admin=is_first)
        u_rec["password_hash"] = rec.get("pw_hash", generate_password_hash(secrets.token_hex(16)))
        u_rec["email_verified"] = True
        users[username] = u_rec
        data["users"] = users
        save_users(data)
        # Platform provides AI — mark preferred_ai step complete so users aren't asked to add a key
        try: _mark_onboarding_step(username, "preferred_ai", True)
        except Exception: pass

    if not is_first and seat_code:
        try:
            _claim_seat_code(seat_code, username)
        except Exception:
            pass

    # Consume the pending token
    pending.pop(token, None)
    _save_pending_verifications(pending)
    session.pop("_pending_verify_token", None)

    session["user"] = username
    session.permanent = True
    _audit_log("register", {"email": email, "is_admin": is_first}, username=username)

    # Welcome email — fire-and-forget
    if email and not is_first:
        _base = (PUBLIC_BASE_URL or "").rstrip("/") or "https://simplyagentic.ai"
        threading.Thread(target=_send_platform_email, args=(
            email,
            f"Welcome to Simply Agentic AI — you're in 🎉",
            f"""Hi {username},

Welcome to Simply Agentic AI — your AI-powered business command center.

Here's how to get started in the next 5 minutes:

1. Open the Command Center and click any teammate seat to start a conversation.
2. Press keys 1–7 on your keyboard to switch between teammates instantly.
3. Type ? at any time to see all keyboard shortcuts.
4. Head to Settings to connect your OpenAI key for the best results.

Your team is ready. Press 1 and say hello to Sunshine.

If you ever need help, just reply to this email.

— The Simply Agentic AI Team
{_base}
""",
        ), daemon=True).start()

    return redirect(url_for("index"))

@app.get("/verify/resend")
def verify_resend():
    token = session.get("_pending_verify_token", "")
    if not token:
        return redirect(url_for("register_get"))
    pending = _load_pending_verifications()
    rec = pending.get(token)
    if not rec:
        return redirect(url_for("register_get"))
    # Issue a fresh code
    new_code = str(secrets.randbelow(900000) + 100000)
    rec["code"] = new_code
    rec["created_at"] = now_iso()
    pending[token] = rec
    _save_pending_verifications(pending)
    try:
        send_email_smtp(
            to_addr=rec["email"],
            subject=f"Your {APP_TITLE} verification code (resent)",
            body=(
                f"Hi {rec['username']},\n\n"
                f"Your new verification code is: {new_code}\n\n"
                f"— {SMTP_FROM_NAME or APP_TITLE}"
            ),
            from_name=SMTP_FROM_NAME or APP_TITLE,
            from_addr=SMTP_USER,
        )
    except Exception:
        pass
    return render_template_string(_VERIFY_HTML, app_title=APP_TITLE,
        email=rec.get("email",""), error=None)


