@app.post("/stripe/create_checkout")
def stripe_create_checkout():
    """Redirect the visitor to a Stripe Checkout session for the selected plan."""
    if not _stripe_ready():
        # Try direct payment link as fallback
        plan_key_fb = _normalize_plan_key((request.get_json(silent=True) or {}).get("plan", "solo"))
        payment_link = _get_payment_link(plan_key_fb)
        if payment_link:
            return jsonify({"ok": True, "payment_link": payment_link})
        return jsonify({"ok": False, "error": "Stripe is not configured on this server."}), 400

    payload  = request.get_json(silent=True) or {}
    plan_key = _normalize_plan_key((payload.get("plan") or request.form.get("plan") or "solo").strip().lower())
    if plan_key not in PLANS:
        plan_key = "solo"

    price_id = _plan_price_id(plan_key)
    if not price_id:
        return jsonify({"ok": False, "error": f"No price ID configured for plan '{plan_key}'."}), 400

    # Founder plan: check availability before sending to Stripe
    if plan_key == "founder":
        if _founder_seats_remaining() <= 0:
            return redirect(f"{PUBLIC_BASE_URL or request.host_url.rstrip('/')}/pricing?founder_sold_out=1", 303)

    base = (PUBLIC_BASE_URL or request.host_url.rstrip("/"))
    # {CHECKOUT_SESSION_ID} is a Stripe template variable — Stripe fills it in automatically.
    success_url = f"{base}/register?stripe_session={{CHECKOUT_SESSION_ID}}&plan={plan_key}"
    cancel_url  = f"{base}/pricing"

    checkout_params = {
        "payment_method_types[]": "card",
        "line_items[0][price]":    price_id,
        "line_items[0][quantity]": "1",
        "mode":                    STRIPE_MODE,
        "allow_promotion_codes":   "true",
        "success_url":             success_url,
        "cancel_url":              cancel_url,
    }
    # Attach free trial to subscription mode checkouts
    if FREE_TRIAL_DAYS > 0 and STRIPE_MODE == "subscription":
        checkout_params["subscription_data[trial_period_days]"] = str(FREE_TRIAL_DAYS)
        # Collect payment method upfront but don't charge until trial ends
        checkout_params["payment_method_collection"] = "always"
    status, data = _stripe_api("POST", "/checkout/sessions", checkout_params)
    if status >= 400:
        err = (data.get("error") or {}).get("message") or "Stripe error"
        return jsonify({"ok": False, "error": err}), 400

    checkout_url = data.get("url")
    if not checkout_url:
        return jsonify({"ok": False, "error": "No checkout URL returned by Stripe."}), 500

    # Return JSON so the browser JS can do window.location.href — a direct
    # server-side redirect(303) to Stripe's domain is cross-origin and gets
    # blocked by CORS when called via fetch(), causing the "Could not connect"
    # error the user sees.
    return jsonify({"ok": True, "url": checkout_url})


def _get_payment_link(plan_key: str) -> str:
    """Return a direct Stripe payment link for a plan, if configured."""
    links = {
        "founder": STRIPE_LINK_FOUNDER,
        "solo":    STRIPE_LINK_SOLO,
        "teams":   STRIPE_LINK_TEAMS,
    }
    return (links.get(plan_key) or "").strip()


@app.post("/stripe/webhook")
def stripe_webhook():
    """
    Stripe sends POST events here.
    Set your webhook endpoint in the Stripe dashboard to:
      https://your-app.com/stripe/webhook
    Subscribe to ALL of these events:
      checkout.session.completed
      customer.subscription.trial_will_end
      customer.subscription.deleted
      customer.subscription.updated
      invoice.paid
      invoice.payment_failed
    """
    payload    = request.get_data()
    sig_header = request.headers.get("Stripe-Signature", "")

    ok, event = _stripe_verify_webhook(payload, sig_header)
    if not ok:
        return jsonify({"error": "Invalid signature"}), 400

    if event.get("type") == "checkout.session.completed":
        obj         = (event.get("data") or {}).get("object") or {}
        session_id  = obj.get("id") or ""
        customer_id = obj.get("customer") or ""
        details     = obj.get("customer_details") or {}
        email       = (details.get("email") or obj.get("customer_email") or "")
        name        = (details.get("name") or "").strip()
        # Detect plan from the price ID — must expand line_items via API (not in webhook payload)
        plan = "solo"
        paid_price = ""
        if session_id and STRIPE_SECRET_KEY:
            try:
                _st, _sd = _stripe_api("GET", f"/checkout/sessions/{session_id}", {"expand[]": "line_items"})
                paid_price = ((_sd.get("line_items") or {}).get("data") or [{}])[0].get("price", {}).get("id", "")
            except Exception:
                paid_price = ""
        if not paid_price:
            # Fallback: check metadata or amount_total on the raw object
            try:
                paid_price = ((obj.get("line_items") or {}).get("data") or [{}])[0].get("price", {}).get("id", "")
            except Exception:
                paid_price = ""
        if paid_price:
            for pk, pv in PLANS.items():
                if pv.get("price_id") == paid_price:
                    plan = pk
                    break
        if session_id:
            _generate_seat_for_stripe(email, customer_id, session_id, name=name, plan=plan)

    # Trial ending soon — send email 3 days before
    if event.get("type") == "customer.subscription.trial_will_end":
        try:
            sub_obj     = (event.get("data") or {}).get("object") or {}
            customer_id = sub_obj.get("customer") or ""
            trial_end   = sub_obj.get("trial_end") or 0
            append_log("stripe_trial_will_end", {
                "customer_id": customer_id,
                "trial_end_epoch": trial_end,
                "at": now_iso(),
            })
            if customer_id:
                seats = (_load_seats().get("seats") or {})
                for seat in seats.values():
                    if seat.get("stripe_customer_id") == customer_id:
                        to_email  = (seat.get("holder_email") or seat.get("stripe_email") or "").strip()
                        plan_name = seat.get("plan_name", "Simply Agentic AI")
                        if to_email:
                            _base = (PUBLIC_BASE_URL or "").rstrip("/") or "https://simplyagentic.ai"
                            threading.Thread(target=_send_platform_email, args=(
                                to_email,
                                "Your Simply Agentic AI trial ends in 3 days",
                                f"""Hi there,

Your free trial of Simply Agentic AI ({plan_name}) ends in 3 days.

After that, your card on file will be charged and you'll keep full access — no action needed.

To change or cancel before the trial ends:
{_base}/stripe/manage

Questions? Just reply to this email.

— The Simply Agentic AI Team
{_base}
""",
                            ), daemon=True).start()
                        break
        except Exception as exc:
            print(f"[WEBHOOK] trial_will_end error: {exc}", flush=True)

    # Subscription cancelled — revoke access and send confirmation
    if event.get("type") == "customer.subscription.deleted":
        try:
            sub_obj     = (event.get("data") or {}).get("object") or {}
            customer_id = sub_obj.get("customer") or ""
            if customer_id:
                data  = _load_seats()
                seats = data.get("seats") or {}
                changed        = False
                cancelled_email = ""
                cancelled_plan  = ""
                for code, seat in seats.items():
                    if seat.get("stripe_customer_id") == customer_id:
                        seats[code]["status"]       = "cancelled"
                        seats[code]["cancelled_at"] = now_iso()
                        cancelled_email = (seat.get("holder_email") or seat.get("stripe_email") or "").strip()
                        cancelled_plan  = seat.get("plan_name", "Simply Agentic AI")
                        changed = True
                if changed:
                    data["seats"] = seats
                    _save_seats(data)
                append_log("stripe_subscription_cancelled", {"customer_id": customer_id, "at": now_iso()})
                if cancelled_email:
                    _base = (PUBLIC_BASE_URL or "").rstrip("/") or "https://simplyagentic.ai"
                    threading.Thread(target=_send_platform_email, args=(
                        cancelled_email,
                        "Your Simply Agentic AI subscription has been cancelled",
                        f"""Hi there,

We've confirmed your Simply Agentic AI subscription ({cancelled_plan}) has been cancelled.

Your data is preserved for 30 days. To reactivate at any time:
{_base}/pricing

We'd love to know what we could have done better — just reply to this email.

— The Simply Agentic AI Team
""",
                    ), daemon=True).start()
        except Exception as exc:
            print(f"[WEBHOOK] subscription.deleted error: {exc}", flush=True)

    # Payment failed — notify user to update card
    if event.get("type") == "invoice.payment_failed":
        try:
            obj2          = (event.get("data") or {}).get("object") or {}
            customer_id   = obj2.get("customer") or ""
            attempt_count = obj2.get("attempt_count", 1)
            if customer_id:
                seats = (_load_seats().get("seats") or {})
                for seat in seats.values():
                    if seat.get("stripe_customer_id") == customer_id:
                        to_email  = (seat.get("holder_email") or seat.get("stripe_email") or "").strip()
                        plan_name = seat.get("plan_name", "Simply Agentic AI")
                        if to_email:
                            _base = (PUBLIC_BASE_URL or "").rstrip("/") or "https://simplyagentic.ai"
                            threading.Thread(target=_send_platform_email, args=(
                                to_email,
                                "Action needed: payment failed for Simply Agentic AI",
                                f"""Hi there,

We couldn't process your payment for Simply Agentic AI ({plan_name}).

This is attempt {attempt_count}. Stripe will retry automatically, but to avoid interruption please update your payment method now:
{_base}/stripe/manage

Need help? Just reply to this email.

— The Simply Agentic AI Team
""",
                            ), daemon=True).start()
                        append_log("stripe_payment_failed", {
                            "customer_id": customer_id,
                            "attempt_count": attempt_count,
                            "at": now_iso(),
                        })
                        break
        except Exception as exc:
            print(f"[WEBHOOK] invoice.payment_failed error: {exc}", flush=True)

    # Trial converted to paid — mark seat trial_active = False
    if event.get("type") in ("invoice.paid", "customer.subscription.updated"):
        try:
            obj2        = (event.get("data") or {}).get("object") or {}
            customer_id = obj2.get("customer") or ""
            if customer_id:
                data  = _load_seats()
                seats = data.get("seats") or {}
                changed = False
                for code, seat in seats.items():
                    if seat.get("stripe_customer_id") == customer_id and seat.get("trial_active"):
                        seats[code]["trial_active"] = False
                        changed = True
                if changed:
                    data["seats"] = seats
                    _save_seats(data)
        except Exception:
            pass

    return jsonify({"ok": True})


@app.get("/stripe/status")
def stripe_status():
    """Admin-only debug endpoint — shows what Stripe env vars the server has loaded."""
    u = current_user()
    if not _is_admin_user(u):
        return jsonify({"error": "Admin only"}), 403
    return jsonify({
        "stripe_ready":            _stripe_ready(),
        "STRIPE_SECRET_KEY_set":   bool(STRIPE_SECRET_KEY),
        "STRIPE_SECRET_KEY_prefix": STRIPE_SECRET_KEY[:7] + "..." if STRIPE_SECRET_KEY else "(not set)",
        "STRIPE_PRICE_ID_set":     bool(STRIPE_PRICE_ID),
        "STRIPE_PRICE_ID":         STRIPE_PRICE_ID or "(not set)",
        "STRIPE_WEBHOOK_SECRET_set": bool(STRIPE_WEBHOOK_SECRET),
        "STRIPE_MODE":             STRIPE_MODE,
        "PUBLIC_BASE_URL":         PUBLIC_BASE_URL or "(not set)",
    })

@app.get("/stripe/manage")
def stripe_manage():
    """Redirect the logged-in user to their Stripe Billing Portal to manage or cancel their subscription.
    The portal handles plan changes, payment method updates, and cancellations — Stripe built-in UI,
    no extra code needed on our side. Requires STRIPE_SECRET_KEY to be set.
    """
    u = current_user()
    if not u:
        return redirect(url_for("login"))
    if not STRIPE_SECRET_KEY:
        return "Billing portal is not configured.", 503

    uname = u.get("username", "")
    # Look up the Stripe customer ID from their seat record
    customer_id = ""
    try:
        seats = (_load_seats().get("seats") or {})
        for seat in seats.values():
            if seat.get("claimed_by") == uname and seat.get("stripe_customer_id"):
                customer_id = seat["stripe_customer_id"]
                break
    except Exception:
        pass

    if not customer_id:
        return (
            "<html><body style='font-family:system-ui;padding:40px;'>"
            "<h2>No billing record found</h2>"
            "<p>Your account does not have a Stripe subscription on record. "
            "If you believe this is an error, please contact support.</p>"
            "<a href='/'>← Back</a></body></html>"
        ), 404

    return_url = (PUBLIC_BASE_URL or request.host_url.rstrip("/")) + "/"
    status, data = _stripe_api("POST", "/billing_portal/sessions", {
        "customer": customer_id,
        "return_url": return_url,
    })
    if status != 200 or not data.get("url"):
        err = (data.get("error") or {}).get("message", "Unknown error")
        return f"Could not open billing portal: {err}", 502
    return redirect(data["url"])

@app.get("/api/stripe/portal_url")
def api_stripe_portal_url():
    """JSON endpoint — returns the billing portal URL for the current user's frontend."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    if not STRIPE_SECRET_KEY:
        return jsonify({"ok": False, "error": "Billing portal not configured"})

    uname = u.get("username", "")
    customer_id = ""
    try:
        seats = (_load_seats().get("seats") or {})
        for seat in seats.values():
            if seat.get("claimed_by") == uname and seat.get("stripe_customer_id"):
                customer_id = seat["stripe_customer_id"]
                break
    except Exception:
        pass

    if not customer_id:
        return jsonify({"ok": False, "error": "No billing record found for this account"})

    return_url = (PUBLIC_BASE_URL or request.host_url.rstrip("/")) + "/"
    status, data = _stripe_api("POST", "/billing_portal/sessions", {
        "customer": customer_id,
        "return_url": return_url,
    })
    if status != 200 or not data.get("url"):
        err = (data.get("error") or {}).get("message", "Unknown error")
        return jsonify({"ok": False, "error": err})
    return jsonify({"ok": True, "url": data["url"]})



@app.get("/reset")
def reset():
    return render_template_string(RESET_HTML, app_title=APP_TITLE, error=None, token=None, ok=None)

@app.post("/reset")
def reset_post():
    # Rate-limit password reset requests: 5 per hour per IP to prevent token spam
    _ip = _get_client_ip() or "unknown"
    _rl_ok, _rl_msg = _rate_limit_check(f"reset:{_ip}", 5)
    if not _rl_ok:
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error="Too many reset attempts. Please wait before trying again.", token=None, ok=None)
    username = _clean_username(request.form.get("username", ""))
    data = load_users()
    u = (data.get("users") or {}).get(username)
    if not u:
        # Return same message regardless of whether username exists (prevents enumeration)
        return render_template_string(RESET_HTML, app_title=APP_TITLE,
            ok="If that username exists, a reset link has been sent to the associated email.",
            error=None, token=None)

    token = _make_token()
    u.setdefault("reset", {})
    u["reset"]["token_hash"] = _hash_token(token)
    u["reset"]["created_at"] = now_iso()
    u["updated_at"] = now_iso()

    data["users"][username] = u
    save_users(data)
    _audit_log("password_reset_requested", {}, username=username)

    # Try to email the token if the user has an email address on file
    user_email = (u.get("email") or "").strip()
    sent_email = False
    if user_email:
        try:
            reset_body = (
                f"Hello {username},\n\n"
                f"You requested a password reset for {APP_TITLE}.\n\n"
                f"Your reset token is:\n\n    {token}\n\n"
                f"Enter this token at {PUBLIC_BASE_URL or 'the app'}/reset to set a new password.\n"
                f"This token expires in 1 hour.\n\n"
                f"If you did not request this, ignore this email.\n"
            )
            # Try SMTP (global server settings) for password reset emails
            if SMTP_USER and SMTP_PASS:
                send_email_smtp(user_email, f"Password Reset - {APP_TITLE}", reset_body,
                                SMTP_FROM_NAME, SMTP_USER)
                sent_email = True
        except Exception:
            pass

    if sent_email:
        ok_msg = f"Reset token sent to {user_email}. Check your inbox (and spam folder)."
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error=None, token=None, ok=ok_msg)
    elif user_email:
        # Email on file but SMTP not configured — log token securely, never expose in HTML
        _audit_log("password_reset_token_generated", {"note": f"token_hash={_hash_token(token)}"}, username=username)
        append_log("reset_token_no_smtp", {"username": username, "token_hash": _hash_token(token), "at": now_iso()})
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error=None, token=None,
            ok="Email delivery is not configured. An admin must retrieve the reset token from the server admin panel (/admin/errors) to complete this reset.")
    else:
        # No email on account — log token securely, never expose in HTML
        _audit_log("password_reset_token_generated", {"note": f"token_hash={_hash_token(token)}"}, username=username)
        append_log("reset_token_no_email", {"username": username, "token_hash": _hash_token(token), "at": now_iso()})
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error=None, token=None,
            ok="No email address is on file for this account. An admin must retrieve the reset token from the server admin panel to complete this reset.")

@app.post("/reset_password")
def reset_password_post():
    username = _clean_username(request.form.get("username", ""))
    token = (request.form.get("token") or "").strip()
    new_password = (request.form.get("new_password") or "").strip()

    _pw_ok, _pw_err = _validate_password_strength(new_password)
    if not _pw_ok:
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error=_pw_err, token=None, ok=None)

    data = load_users()
    u = (data.get("users") or {}).get(username)
    if not u:
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error="Unknown username", token=None, ok=None)

    th = ((u.get("reset") or {}).get("token_hash")) or ""
    computed = _hash_token(token)
    if not th or not hmac.compare_digest(computed, th):
        return render_template_string(RESET_HTML, app_title=APP_TITLE, error="Invalid reset token.", token=None, ok=None)

    # Token expires after 1 hour
    token_created = ((u.get("reset") or {}).get("created_at")) or ""
    if token_created:
        try:
            created_dt = datetime.fromisoformat(token_created.replace("Z", ""))
            if datetime.utcnow() > created_dt + timedelta(hours=1):
                u["reset"]["token_hash"] = ""
                u["reset"]["created_at"] = None
                data["users"][username] = u
                save_users(data)
                return render_template_string(RESET_HTML, app_title=APP_TITLE, error="Reset token has expired. Please request a new one.", token=None, ok=None)
        except Exception:
            pass

    u["password_hash"] = generate_password_hash(new_password)
    u["reset"]["token_hash"] = ""
    u["reset"]["created_at"] = None
    u["updated_at"] = now_iso()
    data["users"][username] = u
    save_users(data)
    _audit_log("password_reset_completed", {}, username=username)

    return render_template_string(RESET_HTML, app_title=APP_TITLE, error=None, token=None, ok="Password updated. You can log in now.")


