@app.get("/api/crm/broadcast/job/<job_id>/stream")
def api_broadcast_job_stream(job_id: str):
    """SSE stream for real-time broadcast progress."""
    from flask import Response, stream_with_context
    import time as _t
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    _uname_stream = (u.get("username") if isinstance(u, dict) else None) or ""
    _job_check = _BROADCAST_JOBS.get(job_id)
    if _job_check and _job_check.get("username") and _job_check["username"] != _uname_stream:
        return jsonify({"ok": False, "error": "Job not found"}), 404
    import json as _json
    def _generate():
        for _ in range(120):
            job = _BROADCAST_JOBS.get(job_id)
            if not job:
                yield f"data: {_json.dumps({'error': 'Job not found'})}\n\n"
                break
            yield f"data: {_json.dumps(job)}\n\n"
            if job.get("status") in ("done", "error"):
                break
            _t.sleep(0.8)
    return Response(stream_with_context(_generate()), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


