# WEBSITE / LANDING PAGE ANALYZER
# =========================
@app.post("/api/analyze/website")
def api_analyze_website():
    """Fetch a URL and run a 1-100 scoring analysis on it. Streams heartbeats to survive Render's 30s proxy timeout."""
    import json as _json2, threading as _thr2, time as _ti2
    from flask import stream_with_context, Response as _Resp2
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    data = request.get_json(silent=True) or {}
    url = (data.get("url") or "").strip()
    if not url: return jsonify({"ok": False, "error": "URL required"}), 400

    system = (
        "You are an expert conversion rate optimizer, competitive intelligence analyst, and digital marketing strategist. "
        "Analyze the provided website content and return a structured JSON analysis. "
        "Respond ONLY with valid JSON, no markdown, no explanation outside the JSON."
    )

    def _generate():
        _done = [False]
        _result = [None]
        _error = [None]

        def _worker():
          with app.app_context():
            try:
                content, err = _fetch_url_content(url, max_chars=10000)
                if err or not content:
                    _error[0] = err or "Could not fetch page content"
                    return
                prompt = f"""Analyze this website content from {url} and return JSON in exactly this format:
{{
  "score": <integer 1-100>,
  "grade": "<A/B/C/D/F>",
  "summary": "<2-3 sentence overall verdict — what they do well and where they fall short>",
  "strengths": ["<strength 1>", "<strength 2>", "<strength 3>"],
  "weaknesses": ["<weakness 1>", "<weakness 2>", "<weakness 3>"],
  "quick_wins": [
    {{"action": "<specific actionable improvement>", "impact": "<High/Medium/Low>", "effort": "<Low/Medium/High>"}},
    {{"action": "<specific actionable improvement>", "impact": "<High/Medium/Low>", "effort": "<Low/Medium/High>"}},
    {{"action": "<specific actionable improvement>", "impact": "<High/Medium/Low>", "effort": "<Low/Medium/High>"}}
  ],
  "categories": {{
    "clarity": <1-10>,
    "design": <1-10>,
    "copy": <1-10>,
    "cta": <1-10>,
    "trust": <1-10>,
    "mobile": <1-10>,
    "speed_signals": <1-10>,
    "seo": <1-10>
  }},
  "content_strategy": "<1-2 sentences: what content approach they use — blog, video, long-form, testimonials, etc.>",
  "tech_signals": "<comma-separated list of tools/tech you can detect from the page — e.g. Shopify, WordPress, Typeform, Intercom, Google Fonts>",
  "seo_summary": "<1-2 sentences on their keyword focus and SEO approach based on headings, meta, and copy>",
  "target_audience": "<who they are clearly targeting based on the content and messaging>",
  "how_to_compete": "<2-3 specific sentences: if you were a competitor, what angle or gap would you exploit to beat this site? Be direct and actionable.>"
}}

Website content:
{content[:6000]}"""
                raw = call_llm(system, [{"role": "user", "content": prompt}], temperature=0.2)
                raw = raw.strip()
                if raw.startswith("```"):
                    raw = raw.split("```")[1]
                    if raw.startswith("json"):
                        raw = raw[4:]
                result = _json2.loads(raw)
                _result[0] = result
            except _json2.JSONDecodeError:
                _error[0] = "Could not parse AI response. Try again."
            except Exception as ex:
                _, msg = _classify_openai_error(ex)
                _error[0] = msg
            finally:
                _done[0] = True

        t = _thr2.Thread(target=_worker, daemon=True)
        t.start()
        while not _done[0]:
            yield (": heartbeat\n\n" + " " * 512 + "\n")
            _ti2.sleep(4)
        t.join(timeout=2)

        if _error[0]:
            yield _json2.dumps({"ok": False, "error": _error[0]}) + "\n"
        else:
            yield _json2.dumps({"ok": True, "url": url, "analysis": _result[0]}) + "\n"

    return _Resp2(stream_with_context(_generate()), content_type="text/plain; charset=utf-8",
                  headers={"Cache-Control": "no-store", "X-Accel-Buffering": "no"})

