@app.get("/unsubscribe/<token>")
def unsubscribe_page(token: str):
    """One-click unsubscribe. Validates the signed token and marks the contact."""
    username, email = _verify_unsub_token(token)
    if not username or not email:
        return "<h2 style='font-family:sans-serif;padding:2rem'>Invalid or expired unsubscribe link.</h2>", 400
    try:
        crm = _crm_load(username)
        clients = crm.get("clients") or {}
        found = False
        for cid, c in clients.items():
            if isinstance(c, dict) and (c.get("email") or "").strip().lower() == email.lower():
                c["email_unsubscribed"] = True
                c["unsubscribed_at"] = now_iso()
                c["updated_at"] = now_iso()
                clients[cid] = c
                found = True
        if found:
            crm["clients"] = clients
            _crm_save(username, crm)
    except Exception:
        pass
    return """<!doctype html><html><head><meta charset=utf-8>
<title>Unsubscribed</title>
<style>body{font-family:sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;background:#f9f9f9}
.box{text-align:center;padding:2rem;background:#fff;border-radius:12px;border:1px solid #e5e5e5;max-width:400px}</style>
</head><body><div class="box">
<h2 style="margin:0 0 .5rem">You've been unsubscribed</h2>
<p style="color:#666;margin:0">You will no longer receive broadcast emails from this account.</p>
</div></body></html>"""


@app.get("/api/user/export")
def api_user_export():
    """GDPR-compliant data export. Returns a ZIP of all the user's data as JSON files.
    Covers: profile, threads, CRM, uploads index, task log, usage log, settings (keys redacted)."""
    import zipfile, io
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:

        # 1. Profile (redact sensitive keys)
        try:
            profile = dict(u)
            profile.pop("password_hash", None)
            settings = dict(profile.get("settings") or {})
            for k in ["openai_key", "claude_key", "smtp_pass"]:
                if k in settings:
                    settings[k] = "[redacted]"
            profile["settings"] = settings
            zf.writestr("profile.json", json.dumps(profile, indent=2))
        except Exception as e:
            zf.writestr("profile.json", json.dumps({"error": str(e)}))

        # 2. Operator profile
        try:
            op = _load_operator_profile(uname) or {}
            zf.writestr("operator_profile.json", json.dumps(op, indent=2))
        except Exception as e:
            zf.writestr("operator_profile.json", json.dumps({"error": str(e)}))

        # 3. All teammate threads
        try:
            reg = load_registry(uname)
            threads = {}
            for name in reg.get("installed", {}):
                try:
                    threads[name] = load_thread(name, uname)
                except Exception:
                    pass
            zf.writestr("threads.json", json.dumps(threads, indent=2))
        except Exception as e:
            zf.writestr("threads.json", json.dumps({"error": str(e)}))

        # 4. CRM data
        try:
            crm = _crm_load(uname)
            crm_clean = dict(crm)
            zf.writestr("crm.json", json.dumps(crm_clean, indent=2))
        except Exception as e:
            zf.writestr("crm.json", json.dumps({"error": str(e)}))

        # 5. Task log (last 1000)
        try:
            logs = read_task_log(limit=1000)
            zf.writestr("task_log.json", json.dumps(logs, indent=2))
        except Exception as e:
            zf.writestr("task_log.json", json.dumps({"error": str(e)}))

        # 6. Token usage log (last 1000)
        try:
            usage = _read_token_usage(uname, limit=1000)
            zf.writestr("token_usage.json", json.dumps(usage, indent=2))
        except Exception as e:
            zf.writestr("token_usage.json", json.dumps({"error": str(e)}))

        # 7. Upload index (filenames only, no binary data)
        try:
            _idx = load_json(UPLOAD_INDEX_PATH, {})
            all_uploads = [r for r in (_idx.get("files") or {}).values()
                          if isinstance(r, dict) and r.get("owner") == uname]
            safe = [{k: v for k, v in r.items() if k not in ("data", "content")}
                    for r in all_uploads]
            zf.writestr("uploads_index.json", json.dumps(safe, indent=2))
        except Exception as e:
            zf.writestr("uploads_index.json", json.dumps({"error": str(e)}))

        # 8. Export manifest
        zf.writestr("README.txt",
            f"Simply Agentic AI — data export for user: {uname}\n"
            f"Exported at: {now_iso()}\n"
            f"Contains: profile, operator_profile, threads, crm, task_log, token_usage, uploads_index\n"
            f"Sensitive keys have been redacted from profile.json.\n"
        )

    buf.seek(0)
    from flask import send_file
    return send_file(
        buf,
        mimetype="application/zip",
        as_attachment=True,
        download_name=f"simply_agentic_export_{uname}_{datetime.utcnow().strftime('%Y%m%d')}.zip",
    )

@app.get("/api/team")
def api_team_get():
    """Return the current user's team info: members, seats used, limit."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname      = u.get("username", "")
    owner_name = _get_team_owner(uname)
    # If this user is a team member, return their owner's team info
    effective_owner = owner_name if owner_name else uname
    plan       = _get_user_plan(effective_owner)
    limit      = _team_seat_limit(plan)
    members    = _get_team_members(effective_owner)
    used       = 1 + len(members)
    plan_info  = PLANS.get(plan) or {}
    return jsonify({
        "ok":          True,
        "owner":       effective_owner,
        "is_owner":    not bool(owner_name),
        "plan":        plan,
        "plan_name":   plan_info.get("name", plan),
        "seats_limit": limit,
        "seats_used":  used,
        "seats_left":  max(0, limit - used),
        "members":     members,
    })


@app.post("/api/team/add")
def api_team_add():
    """Owner adds a team member by username."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname  = u.get("username", "")
    # Only owners (not team members themselves) can add members
    if _get_team_owner(uname):
        return jsonify({"ok": False, "error": "Team members cannot invite others — contact your account owner."}), 403
    payload = request.get_json(silent=True) or {}
    member  = (payload.get("username") or "").strip().lower()
    if not member:
        return jsonify({"ok": False, "error": "Username required."}), 400
    if member == uname:
        return jsonify({"ok": False, "error": "You can't add yourself."}), 400
    ok, err = _add_team_member(uname, member)
    if not ok:
        return jsonify({"ok": False, "error": err}), 400
    return jsonify({"ok": True, "message": f"{member} added to your team."})


@app.post("/api/team/remove")
def api_team_remove():
    """Owner removes a team member by username."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname  = u.get("username", "")
    if _get_team_owner(uname):
        return jsonify({"ok": False, "error": "Only the account owner can remove team members."}), 403
    payload = request.get_json(silent=True) or {}
    member  = (payload.get("username") or "").strip().lower()
    if not member:
        return jsonify({"ok": False, "error": "Username required."}), 400
    ok, err = _remove_team_member(uname, member)
    if not ok:
        return jsonify({"ok": False, "error": err}), 400
    return jsonify({"ok": True, "message": f"{member} removed from your team."})


