#  VIDEO EDITOR
# ═══════════════════════════════════════════════════════════════════
import subprocess as _subprocess_ve
import shutil as _shutil_ve

import tempfile as _tempfile_ve
_VE_TEMP = Path(_tempfile_ve.gettempdir()) / "sa_video"

def _ve_cleanup_old():
    try:
        import time as _t
        cutoff = _t.time() - 7200  # 2 hours
        if _VE_TEMP.exists():
            for d in _VE_TEMP.iterdir():
                if d.is_dir() and d.stat().st_mtime < cutoff:
                    _shutil_ve.rmtree(d, ignore_errors=True)
    except Exception:
        pass

_VE_MIME_MAP = {
    'mp4': 'video/mp4', 'webm': 'video/webm',
    'mov': 'video/quicktime', 'avi': 'video/x-msvideo', 'mkv': 'video/x-matroska'
}

@app.get("/api/video/stream/<vid_id>")
def api_video_stream(vid_id):
    """Serve the uploaded video with HTTP range-request support so the browser can seek."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    if not re.match(r'^[a-f0-9]+$', vid_id):
        return jsonify({"ok": False, "error": "Invalid ID"}), 400
    vid_dir = _VE_TEMP / vid_id
    orig_files = list(vid_dir.glob("original.*")) if vid_dir.exists() else []
    if not orig_files:
        return jsonify({"ok": False, "error": "Video not found — please re-upload."}), 404
    orig_path = orig_files[0]
    ext  = orig_path.suffix.lstrip('.').lower()
    mime = _VE_MIME_MAP.get(ext, 'video/mp4')
    from flask import send_file as _sf
    return _sf(str(orig_path), mimetype=mime, conditional=True)

@app.post("/api/video/upload_chunk")
def api_video_upload_chunk():
    """Receive one 3 MB chunk of a chunked video upload."""
    import tempfile as _tvc, json as _jvc, re as _rvc
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    upload_id    = (request.form.get("upload_id") or "").strip()
    chunk_index  = int(request.form.get("chunk_index") or 0)
    total_chunks = int(request.form.get("total_chunks") or 1)
    filename     = (request.form.get("filename") or "upload").strip()
    chunk_file   = request.files.get("chunk")
    if not upload_id or not chunk_file:
        return jsonify({"ok": False, "error": "Missing upload_id or chunk"}), 400
    if not _rvc.match(r'^ve_[0-9]+_[a-z0-9]{4,12}$', upload_id):
        return jsonify({"ok": False, "error": "Invalid upload_id"}), 400
    chunk_dir = Path(_tvc.gettempdir()) / f"sa_vechunk_{upload_id}"
    chunk_dir.mkdir(parents=True, exist_ok=True)
    chunk_file.save(str(chunk_dir / f"chunk_{chunk_index:06d}"))
    (chunk_dir / "meta.json").write_text(_jvc.dumps({"total_chunks": total_chunks, "filename": filename}))
    return jsonify({"ok": True, "chunk": chunk_index})


@app.post("/api/video/upload")
def api_video_upload():
    import tempfile as _tvu, json as _jvu, shutil as _svu
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    threading.Thread(target=_ve_cleanup_old, daemon=True).start()
    content_type = (request.content_type or "").lower()

    if "application/json" in content_type:
        # ── Chunked upload: assemble saved chunks ─────────────────────────────
        body      = request.get_json(silent=True) or {}
        upload_id = (body.get("upload_id") or "").strip()
        filename  = (body.get("filename") or "upload").strip()
        if not upload_id:
            return jsonify({"ok": False, "error": "Missing upload_id"}), 400
        chunk_dir = Path(_tvu.gettempdir()) / f"sa_vechunk_{upload_id}"
        if not chunk_dir.exists():
            return jsonify({"ok": False, "error": "Upload session not found — please re-upload."}), 400
        try:
            meta = _jvu.loads((chunk_dir / "meta.json").read_text())
            total_chunks = int(meta.get("total_chunks", 0))
        except Exception:
            total_chunks = 0
        chunk_files = sorted(chunk_dir.glob("chunk_*"))
        if len(chunk_files) != total_chunks or total_chunks == 0:
            return jsonify({"ok": False, "error": f"Upload incomplete ({len(chunk_files)}/{total_chunks} chunks). Please try again."}), 400
        ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else "mp4"
        if ext not in {"mp4", "mov", "webm", "avi", "mkv"}:
            ext = "mp4"
        vid_id  = uuid.uuid4().hex[:16]
        vid_dir = _VE_TEMP / vid_id
        vid_dir.mkdir(parents=True, exist_ok=True)
        dest = vid_dir / f"original.{ext}"
        try:
            with open(str(dest), "wb") as out_f:
                for cf in chunk_files:
                    out_f.write(cf.read_bytes())
        except Exception as ae:
            return jsonify({"ok": False, "error": f"Assembly failed: {ae}"}), 500
        finally:
            _svu.rmtree(str(chunk_dir), ignore_errors=True)
    else:
        # ── Direct upload (legacy path) ────────────────────────────────────────
        if "file" not in request.files:
            return jsonify({"ok": False, "error": "No file uploaded"}), 400
        f   = request.files["file"]
        ext = (f.filename or "upload").rsplit(".", 1)[-1].lower()
        if ext not in {"mp4", "mov", "webm", "avi", "mkv"}:
            return jsonify({"ok": False, "error": f"Unsupported format .{ext}. Use MP4, MOV, or WEBM."}), 400
        vid_id  = uuid.uuid4().hex[:16]
        vid_dir = _VE_TEMP / vid_id
        vid_dir.mkdir(parents=True, exist_ok=True)
        dest = vid_dir / f"original.{ext}"
        f.save(str(dest))

    size = dest.stat().st_size if dest.exists() else 0
    if size > 500 * 1024 * 1024:
        try: dest.unlink()
        except Exception: pass
        return jsonify({"ok": False, "error": "File exceeds 500 MB limit."}), 400
    print(f"[VE] upload user={u.get('username')} vid={vid_id} size={size} ext={ext}", flush=True)
    return jsonify({"ok": True, "video_id": vid_id})

@app.post("/api/video/autoclip")
def api_video_autoclip():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    body = request.get_json(force=True) or {}
    vid_id = (body.get("video_id") or "").strip()
    duration = float(body.get("duration") or 0)
    if not vid_id:
        return jsonify({"ok": False, "error": "No video_id provided"}), 400
    vid_dir = _VE_TEMP / vid_id
    orig_files = list(vid_dir.glob("original.*")) if vid_dir.exists() else []
    if not orig_files:
        return jsonify({"ok": False, "error": "Video not found — please re-upload."}), 404
    orig_path = orig_files[0]
    user_key = _decrypt_field(((u.get("settings") or {}).get("openai_key") or "").strip())
    openai_key = user_key or (OPENAI_API_KEY or "").strip()
    if not openai_key:
        return jsonify({"ok": False, "error": "Auto-clip requires an OpenAI API key. Add yours in Settings."}), 400
    # Extract audio
    audio_path = vid_dir / "audio.mp3"
    try:
        _subprocess_ve.run(
            ["ffmpeg", "-y", "-i", str(orig_path), "-vn", "-ar", "16000", "-ac", "1", "-b:a", "32k", str(audio_path)],
            check=True, capture_output=True, timeout=180
        )
    except FileNotFoundError:
        return jsonify({"ok": False, "error": "ffmpeg not available on server. Contact support to enable Video Editor."}), 500
    except (_subprocess_ve.CalledProcessError, _subprocess_ve.TimeoutExpired) as e:
        return jsonify({"ok": False, "error": "Audio extraction failed. Video may be corrupted."}), 500
    # Transcribe with Whisper
    try:
        import io as _io
        oai = OpenAI(api_key=openai_key.strip())
        with open(audio_path, "rb") as af:
            result = oai.audio.transcriptions.create(model="whisper-1", file=af, response_format="verbose_json")
        transcript = (result.text or "").strip()
        segments = getattr(result, "segments", None) or []
    except Exception as exc:
        _, msg = _classify_openai_error(exc)
        return jsonify({"ok": False, "error": f"Transcription failed: {msg}"}), 500
    if not transcript:
        return jsonify({"ok": False, "error": "No speech detected. Try a video with clear audio."}), 400
    # Build timestamp text
    seg_text = ""
    if segments:
        for s in segments[:200]:
            try:
                # OpenAI SDK returns Pydantic objects (s.start) not dicts (s.get('start'))
                _s = s.get('start', 0) if isinstance(s, dict) else float(getattr(s, 'start', 0) or 0)
                _e = s.get('end', 0)   if isinstance(s, dict) else float(getattr(s, 'end',   0) or 0)
                _t = s.get('text', '') if isinstance(s, dict) else str(getattr(s,  'text',  '') or '')
                seg_text += f"[{_s:.1f}s-{_e:.1f}s] {_t.strip()}\n"
            except Exception:
                pass
    if not seg_text:
        seg_text = transcript[:3000]
    vid_duration = duration or 60
    prompt = (
        f"You are a short-form video expert like Opus Clips. Analyze this transcript and pick the 3-5 BEST clips "
        f"(15-90 seconds each) for social media. Video is {vid_duration:.0f}s long.\n\n"
        f"Transcript:\n{seg_text}\n\n"
        "Return ONLY a JSON array. Each item: {\"title\": \"...\", \"start\": 12.5, \"end\": 47.0, \"reason\": \"...\"}\n"
        f"Rules: clips 15-90s, start>=0, end<={vid_duration:.0f}, avoid mid-sentence breaks, pick high-energy moments."
    )
    try:
        resp = oai.chat.completions.create(
            model="gpt-4o-mini", messages=[{"role":"user","content":prompt}],
            max_tokens=600, temperature=0.3
        )
        raw = (resp.choices[0].message.content or "").strip()
        match = re.search(r'\[.*?\]', raw, re.DOTALL)
        if not match:
            return jsonify({"ok": False, "error": "AI could not identify clips. Try a longer video with clear speech."}), 400
        clips_raw = json.loads(match.group())
        clips = []
        for c in clips_raw:
            if not isinstance(c, dict): continue
            s = max(0.0, float(c.get("start") or 0))
            e = min(float(vid_duration), float(c.get("end") or 0))
            if e - s < 5: continue
            clips.append({"title": str(c.get("title","Clip"))[:60], "start": round(s,1), "end": round(e,1), "reason": str(c.get("reason",""))[:150]})
        return jsonify({"ok": True, "clips": clips[:5]})
    except Exception as exc:
        _, msg = _classify_openai_error(exc)
        return jsonify({"ok": False, "error": f"AI analysis failed: {msg}"}), 500

@app.post("/api/video/export")
def api_video_export():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    body = request.get_json(force=True) or {}
    vid_id = (body.get("video_id") or "").strip()
    start = float(body.get("start") or 0)
    end = float(body.get("end") or 0)
    if not vid_id:
        return jsonify({"ok": False, "error": "No video_id provided"}), 400
    if end <= start:
        return jsonify({"ok": False, "error": "End must be after start"}), 400
    if end - start > 600:
        return jsonify({"ok": False, "error": "Clip cannot exceed 10 minutes"}), 400
    vid_dir = _VE_TEMP / vid_id
    orig_files = list(vid_dir.glob("original.*")) if vid_dir.exists() else []
    if not orig_files:
        return jsonify({"ok": False, "error": "Video not found — please re-upload."}), 404
    orig_path = orig_files[0]
    export_id = uuid.uuid4().hex[:12]
    out_path = vid_dir / f"clip_{export_id}.mp4"
    mute = bool(body.get("mute"))
    try:
        ffmpeg_args = ["ffmpeg", "-y", "-i", str(orig_path),
            "-ss", str(start), "-t", str(end - start),
            "-c:v", "libx264", "-preset", "fast", "-crf", "23"]
        if mute:
            ffmpeg_args += ["-an"]  # strip audio
        else:
            ffmpeg_args += ["-c:a", "aac", "-b:a", "128k"]
        ffmpeg_args += ["-movflags", "+faststart", str(out_path)]
        _subprocess_ve.run(ffmpeg_args, check=True, capture_output=True, timeout=300)
    except FileNotFoundError:
        return jsonify({"ok": False, "error": "ffmpeg not available. Contact support to enable Video Editor."}), 500
    except (_subprocess_ve.CalledProcessError, _subprocess_ve.TimeoutExpired):
        return jsonify({"ok": False, "error": "Export failed. Video may be corrupted or too large."}), 500
    print(f"[VE] export user={u.get('username')} vid={vid_id} clip={export_id} mute={mute} {start:.1f}-{end:.1f}s", flush=True)
    return jsonify({"ok": True, "export_id": f"{vid_id}/{export_id}"})

@app.post("/api/video/extract_audio")
def api_video_extract_audio():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    body = request.get_json(force=True) or {}
    vid_id = (body.get("video_id") or "").strip()
    start  = float(body.get("start") or 0)
    end    = float(body.get("end") or 0)
    if not vid_id:
        return jsonify({"ok": False, "error": "No video_id provided"}), 400
    vid_dir = _VE_TEMP / vid_id
    orig_files = list(vid_dir.glob("original.*")) if vid_dir.exists() else []
    if not orig_files:
        return jsonify({"ok": False, "error": "Video not found — please re-upload."}), 404
    orig_path = orig_files[0]
    export_id = uuid.uuid4().hex[:12]
    out_path = vid_dir / f"clip_{export_id}.mp3"
    duration_args = ["-t", str(end - start)] if end > start else []
    try:
        _subprocess_ve.run([
            "ffmpeg", "-y", "-i", str(orig_path),
            "-ss", str(start)] + duration_args + [
            "-vn", "-ac", "2", "-ar", "44100", "-b:a", "192k", str(out_path)
        ], check=True, capture_output=True, timeout=300)
    except FileNotFoundError:
        return jsonify({"ok": False, "error": "ffmpeg not available. Contact support to enable Video Editor."}), 500
    except (_subprocess_ve.CalledProcessError, _subprocess_ve.TimeoutExpired):
        return jsonify({"ok": False, "error": "Audio extraction failed."}), 500
    print(f"[VE] extract_audio user={u.get('username')} vid={vid_id} clip={export_id}", flush=True)
    return jsonify({"ok": True, "export_id": f"{vid_id}/{export_id}"})

@app.get("/api/video/download/<path:export_id>")
def api_video_download(export_id):
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    parts = export_id.split("/")
    if len(parts) != 2:
        return jsonify({"ok": False, "error": "Invalid export ID"}), 400
    vid_id, clip_id = parts
    # sanitize
    if not re.match(r'^[a-f0-9]+$', vid_id) or not re.match(r'^[a-f0-9]+$', clip_id):
        return jsonify({"ok": False, "error": "Invalid ID format"}), 400
    # check for mp4 or mp3
    clip_path_mp4 = _VE_TEMP / vid_id / f"clip_{clip_id}.mp4"
    clip_path_mp3 = _VE_TEMP / vid_id / f"clip_{clip_id}.mp3"
    if clip_path_mp3.exists():
        from flask import send_file as _send_file
        return _send_file(str(clip_path_mp3), as_attachment=True, download_name=f"audio_{clip_id}.mp3", mimetype="audio/mpeg")
    if clip_path_mp4.exists():
        from flask import send_file as _send_file
        return _send_file(str(clip_path_mp4), as_attachment=True, download_name=f"clip_{clip_id}.mp4", mimetype="video/mp4")
    return jsonify({"ok": False, "error": "Clip not found or expired"}), 404


@app.post("/api/video/convert_to_mp4")
def api_video_convert_to_mp4():
    """Accept a WebM blob, convert to MP4 with ffmpeg, return the MP4.
    Used by the Teleprompter so recorded videos download as proper MP4 files
    with correct duration metadata instead of durationless WebM."""
    from flask import send_file as _sf
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    if "file" not in request.files:
        return jsonify({"ok": False, "error": "No file uploaded"}), 400
    f = request.files["file"]
    data = f.read()
    if len(data) > 500 * 1024 * 1024:  # 500 MB cap
        return jsonify({"ok": False, "error": "File too large (max 500 MB)"}), 400
    if len(data) < 100:
        return jsonify({"ok": False, "error": "File too small to convert"}), 400

    conv_id = uuid.uuid4().hex[:12]
    conv_dir = _VE_TEMP / f"conv_{conv_id}"
    conv_dir.mkdir(parents=True, exist_ok=True)
    in_path  = conv_dir / "input.webm"
    out_path = conv_dir / "output.mp4"
    in_path.write_bytes(data)
    print(f"[CONVERT] user={u.get('username','?')} size={len(data)} id={conv_id}", flush=True)
    try:
        result = _subprocess_ve.run([
            "ffmpeg", "-y",
            "-i", str(in_path),
            "-c:v", "libx264", "-preset", "medium", "-crf", "18",  # crf 18 = near-lossless quality
            "-c:a", "aac", "-b:a", "320k",                          # max audio quality
            "-movflags", "+faststart",   # moves moov atom to front — required for duration display
            str(out_path)
        ], capture_output=True, timeout=300)
        if result.returncode != 0 or not out_path.exists() or out_path.stat().st_size < 100:
            err = (result.stderr or b"").decode("utf-8", errors="replace")[-400:]
            print(f"[CONVERT] ffmpeg failed: {err}", flush=True)
            return jsonify({"ok": False, "error": "Video conversion failed — your browser may not support MP4 recording directly."}), 500
        print(f"[CONVERT] done size={out_path.stat().st_size}", flush=True)
        return _sf(
            str(out_path),
            as_attachment=True,
            download_name="teleprompter-recording.mp4",
            mimetype="video/mp4"
        )
    except FileNotFoundError:
        return jsonify({"ok": False, "error": "ffmpeg not available on this server."}), 500
    except (_subprocess_ve.CalledProcessError, _subprocess_ve.TimeoutExpired):
        return jsonify({"ok": False, "error": "Conversion timed out — try a shorter recording."}), 500
    finally:
        # Clean up temp files after a short delay (file still being sent)
        import threading as _ct
        def _cleanup():
            import time as _ct_t; _ct_t.sleep(30)
            try: _shutil_ve.rmtree(conv_dir, ignore_errors=True)
            except Exception: pass
        _ct.Thread(target=_cleanup, daemon=True).start()


