def _thread_pins_path(name: str, uname: str) -> Path:
    return DATA / f"thread_pins_{_safe_name(uname)}_{_safe_name(name)}.json"

def load_thread_pins(name: str, uname: str) -> List[str]:
    try:
        d = load_json(_thread_pins_path(name, uname), [])
        return d if isinstance(d, list) else []
    except Exception:
        return []

def save_thread_pins(name: str, uname: str, pins: List[str]) -> None:
    try:
        save_json(_thread_pins_path(name, uname), pins[:50])
    except Exception:
        pass

@app.post("/api/teammate/feedback")
def api_teammate_feedback():
    """Record a thumbs-up or thumbs-down on a teammate reply."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = _get_session_username()
    data = request.get_json(silent=True) or {}
    name      = (data.get("name") or "").strip()
    sentiment = (data.get("sentiment") or "").strip()   # "up" | "down"
    snippet   = (data.get("snippet") or "").strip()[:200]
    if not name or sentiment not in ("up", "down"):
        return jsonify({"ok": False, "error": "Missing name or sentiment"}), 400
    try:
        mem = load_teammate_memory(uname, name)
        style = mem.get("style_notes") or []
        if sentiment == "up":
            note = f"User liked this response style: {snippet}" if snippet else "User gave a thumbs up"
        else:
            note = f"User disliked this response style: {snippet}" if snippet else "User gave a thumbs down"
        if not any(note[:40] in s for s in style):
            style.insert(0, note)
            mem["style_notes"] = style[:20]
            save_teammate_memory(uname, name, mem)
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

@app.post("/api/thread/pin")
def api_thread_pin():
    """Toggle a pinned message in a teammate thread."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = _get_session_username()
    data = request.get_json(silent=True) or {}
    name    = (data.get("name") or "").strip()
    text    = (data.get("text") or "").strip()
    action  = (data.get("action") or "toggle").strip()   # "pin" | "unpin" | "toggle"
    if not name or not text:
        return jsonify({"ok": False, "error": "Missing name or text"}), 400
    pins = load_thread_pins(name, uname)
    key = text[:120]
    exists = any(p[:120] == key for p in pins)
    if action == "pin" or (action == "toggle" and not exists):
        if not exists:
            pins.insert(0, text[:500])
        save_thread_pins(name, uname, pins)
        return jsonify({"ok": True, "pinned": True, "pins": pins})
    else:
        pins = [p for p in pins if p[:120] != key]
        save_thread_pins(name, uname, pins)
        return jsonify({"ok": True, "pinned": False, "pins": pins})

@app.get("/api/thread/pins")
def api_thread_pins_get():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = _get_session_username()
    name = (request.args.get("name") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "Missing name"}), 400
    return jsonify({"ok": True, "pins": load_thread_pins(name, uname)})

@app.post("/api/teammate/extract_memory")
def api_teammate_extract_memory():
    """Trigger a background memory extraction from recent thread."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = _get_session_username()
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "Missing name"}), 400
    try:
        thread = load_thread(name, uname)
        if len(thread) < 4:
            return jsonify({"ok": True, "skipped": True})
        # Skip extraction if recent messages are all short/trivial — no extractable content
        recent = thread[-10:]
        _user_msgs = [m for m in recent if m.get("role") == "user"]
        _total_user_chars = sum(len(str(m.get("content") or "")) for m in _user_msgs)
        _avg_user_chars = _total_user_chars / max(len(_user_msgs), 1)
        _trivial_words = {"ok", "thanks", "yes", "no", "sure", "great", "cool", "got it",
                          "okay", "yep", "nope", "k", "lol", "haha", "nice", "good", "sounds good"}
        _trivial_count = sum(1 for m in _user_msgs
                             if (str(m.get("content") or "").strip().lower() in _trivial_words
                                 or len(str(m.get("content") or "")) < 20))
        if _avg_user_chars < 30 or _trivial_count >= len(_user_msgs):
            return jsonify({"ok": True, "skipped": True, "reason": "trivial_messages"})
        new_data = _extract_memory_from_thread(name, thread[-20:])
        if new_data:
            existing = load_teammate_memory(uname, name)
            merged = _merge_teammate_memory(existing, new_data)
            save_teammate_memory(uname, name, merged)
        return jsonify({"ok": True, "extracted": bool(new_data)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

# ── Background scheduler: fire Action Stack schedules without needing browser open ──
def _prune_logs_dir(max_files: int = 3000) -> None:
    """Keep only the most recent max_files log entries to prevent disk exhaustion."""
    try:
        if not LOGS_DIR.exists():
            return
        files = sorted(LOGS_DIR.glob("*.json"), key=lambda f: f.stat().st_mtime)
        for f in files[:-max_files]:
            try: f.unlink()
            except Exception: pass
    except Exception:
        pass

_bg_evict_counter = 0

def _bg_schedule_tick():
    """Runs in a daemon thread — checks for due schedules every 60 s.
    This ensures scheduled Action Stacks fire even when no browser tab is open."""
    global _bg_evict_counter
    import time as _bst
    _bst.sleep(15)  # let app fully start first
    while True:
        try:
            with app.app_context():
                _run_due_schedules_once()
        except Exception as _bse:
            _log("WARNING", "Background schedule tick error", error=str(_bse)[:200])
        # Drip campaign tick — run for every active user
        try:
            with app.app_context():
                if CRM_DIR.is_dir():
                    for _dp in CRM_DIR.glob("*_drip.json"):
                        _uname = _dp.stem[:-len("_drip")]
                        try: _drip_tick(_uname)
                        except Exception: pass
        except Exception:
            pass
        # Every 10 minutes: prune logs + evict old image jobs
        _bg_evict_counter += 1
        if _bg_evict_counter % 10 == 0:
            try: _prune_logs_dir()
            except Exception: pass
            try: _image_jobs_evict_old()
            except Exception: pass
        _bst.sleep(60)

_bg_sched_thread = threading.Thread(target=_bg_schedule_tick, daemon=True, name="sa-scheduler")
_bg_sched_thread.start()
print("[STARTUP] Background scheduler started — Action Stacks run without browser", flush=True)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=PORT, debug=False, use_reloader=False, threaded=True)


